//! Small string-similarity helpers used for "did you mean" suggestions.

use std::cmp::{max, min};

/// Jaro similarity between two strings (character based).
pub fn jaro(a: &str, b: &str) -> f64 {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let a_len = a_chars.len();
    let b_len = b_chars.len();

    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    } else if a_len == 1 && b_len == 1 {
        return if a_chars[0] == b_chars[0] { 1.0 } else { 0.0 };
    }

    let search_range = (max(a_len, b_len) / 2) - 1;

    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0_f64;
    let mut transpositions = 0.0_f64;
    let mut b_match_index = 0usize;

    for (i, a_elem) in a_chars.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = min(b_len - 1, i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, b_elem) in b_chars.iter().enumerate() {
            if min_bound <= j && j <= max_bound && a_elem == b_elem && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }

    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

/// Jaro-Winkler similarity (prefix bonus, unbounded prefix length).
pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a
        .chars()
        .zip(b.chars())
        .take_while(|(x, y)| x == y)
        .count();
    let jw = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

/// Returns the best candidate with a confidence strictly above 0.8.
pub fn did_you_mean<'a, I>(value: &str, candidates: I) -> Option<&'a str>
where
    I: IntoIterator<Item = &'a str>,
{
    let mut best: Option<(f64, &'a str)> = None;
    for cand in candidates {
        let confidence = jaro_winkler(value, cand);
        if confidence > 0.8 && best.map_or(true, |(c, _)| c < confidence) {
            best = Some((confidence, cand));
        }
    }
    best.map(|(_, c)| c)
}
EOF
echo done"}

