//! Command line parsing.
//!
//! This is a purpose-built argument parser that mimics the conventions of
//! classic `clap` style interfaces (usage strings, error texts, `--`
//! handling, "did you mean" suggestions, ...).

use crate::help;
use crate::strsim::did_you_mean;
use std::io::IsTerminal;

/// Result of a successful parse.
#[derive(Debug)]
pub struct Cli {
    pub verbose: bool,
    pub config_file: Option<String>,
    pub command: Command,
}

#[derive(Debug)]
pub enum Command {
    /// `pier <alias> [args]...` or `pier run <alias> [args]...`
    Run { alias: String, args: Vec<String> },
    Add {
        alias: String,
        description: Option<String>,
        tags: Option<Vec<String>>,
        force: bool,
        command: Option<String>,
    },
    ConfigInit,
    Copy { from: String, to: String },
    Edit { alias: String },
    List {
        list_aliases: bool,
        cmd_full: bool,
        cmd_width: Option<usize>,
        tags: Option<Vec<String>>,
    },
    Move { from: String, to: String, force: bool },
    Remove { alias: String },
    Show { alias: String },
}

/// Early exit requested by the parser (help, version or an error).
#[derive(Debug)]
pub struct Exit {
    pub message: String,
    pub use_stderr: bool,
    pub code: i32,
}

impl Exit {
    fn out(message: String) -> Self {
        Exit { message, use_stderr: false, code: 0 }
    }
    fn err(message: String) -> Self {
        Exit { message, use_stderr: true, code: 1 }
    }
}

// ---------------------------------------------------------------------------
// Specification of the interface
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Flag,
    /// An option taking a value. `multiple` allows several values.
    Opt { multiple: bool },
    /// A positional argument. `multiple` allows several values.
    Pos { multiple: bool },
}

#[derive(Clone, Copy)]
struct ArgSpec {
    /// Internal name used for sorting in usage strings.
    name: &'static str,
    short: Option<char>,
    long: Option<&'static str>,
    kind: Kind,
    required: bool,
    /// Representation such as `--alias <alias>` or `<alias>`.
    display: &'static str,
    /// Environment variable providing a default value.
    env: Option<&'static str>,
}

const fn flag(name: &'static str, short: char, long: &'static str, display: &'static str) -> ArgSpec {
    ArgSpec { name, short: Some(short), long: Some(long), kind: Kind::Flag, required: false, display, env: None }
}

const fn opt(name: &'static str, short: char, long: &'static str, display: &'static str, required: bool, multiple: bool) -> ArgSpec {
    ArgSpec { name, short: Some(short), long: Some(long), kind: Kind::Opt { multiple }, required, display, env: None }
}

const fn pos(name: &'static str, display: &'static str, required: bool, multiple: bool) -> ArgSpec {
    ArgSpec { name, short: None, long: None, kind: Kind::Pos { multiple }, required, display, env: None }
}

const HELP_FLAG: ArgSpec = flag("help", 'h', "help", "--help");
const VERSION_FLAG: ArgSpec = flag("version", 'V', "version", "--version");

struct SubSpec {
    name: &'static str,
    aliases: &'static [&'static str],
}

struct AppSpec {
    /// Canonical name of the (sub)command, `None` for the root.
    sub_name: Option<&'static str>,
    args: &'static [ArgSpec],
    subcommands: &'static [SubSpec],
    /// Everything after the last positional is treated as values.
    trailing_var_arg: bool,
    /// Usage line(s) shown in help and in errors without context.
    help_usage: &'static str,
}

const ROOT_ARGS: &[ArgSpec] = &[
    HELP_FLAG,
    VERSION_FLAG,
    flag("verbose", 'v', "verbose", "--verbose"),
    ArgSpec {
        name: "config-file",
        short: Some('c'),
        long: Some("config-file"),
        kind: Kind::Opt { multiple: false },
        required: false,
        display: "--config-file <path>",
        env: Some("PIER_CONFIG_PATH"),
    },
    pos("alias", "<alias>", true, false),
    pos("args", "<args>...", false, true),
];

const ROOT_SUBS: &[SubSpec] = &[
    SubSpec { name: "add", aliases: &[] },
    SubSpec { name: "config-init", aliases: &["init"] },
    SubSpec { name: "copy", aliases: &["cp"] },
    SubSpec { name: "edit", aliases: &[] },
    SubSpec { name: "list", aliases: &["ls"] },
    SubSpec { name: "move", aliases: &["mv", "rename"] },
    SubSpec { name: "remove", aliases: &["rm"] },
    SubSpec { name: "run", aliases: &[] },
    SubSpec { name: "show", aliases: &[] },
    SubSpec { name: "help", aliases: &[] },
];

const ROOT: AppSpec = AppSpec {
    sub_name: None,
    args: ROOT_ARGS,
    subcommands: ROOT_SUBS,
    trailing_var_arg: true,
    help_usage: "{bin} [FLAGS] [OPTIONS] <alias> [args]...\n    {bin} [FLAGS] [OPTIONS] <SUBCOMMAND>",
};

const ADD: AppSpec = AppSpec {
    sub_name: Some("add"),
    args: &[
        HELP_FLAG,
        VERSION_FLAG,
        flag("force", 'f', "force", "--force"),
        opt("alias", 'a', "alias", "--alias <alias>", true, false),
        opt("description", 'd', "description", "--description <description>", false, false),
        opt("tags", 't', "tag", "--tag <tags>...", false, true),
        pos("command", "<command>", false, false),
    ],
    subcommands: &[],
    trailing_var_arg: false,
    help_usage: "{bin} add [FLAGS] [OPTIONS] --alias <alias> [--] [command]",
};

const CONFIG_INIT: AppSpec = AppSpec {
    sub_name: Some("config-init"),
    args: &[HELP_FLAG, VERSION_FLAG],
    subcommands: &[],
    trailing_var_arg: false,
    help_usage: "{bin} config-init",
};

const COPY: AppSpec = AppSpec {
    sub_name: Some("copy"),
    args: &[
        HELP_FLAG,
        VERSION_FLAG,
        pos("from-alias", "<from-alias>", true, false),
        pos("to-alias", "<to-alias>", true, false),
    ],
    subcommands: &[],
    trailing_var_arg: false,
    help_usage: "{bin} copy <from-alias> <to-alias>",
};

const EDIT: AppSpec = AppSpec {
    sub_name: Some("edit"),
    args: &[HELP_FLAG, VERSION_FLAG, pos("alias", "<alias>", true, false)],
    subcommands: &[],
    trailing_var_arg: false,
    help_usage: "{bin} edit <alias>",
};

const LIST: AppSpec = AppSpec {
    sub_name: Some("list"),
    args: &[
        HELP_FLAG,
        VERSION_FLAG,
        flag("cmd-full", 'l', "cmd_full", "--cmd_full"),
        flag("list-aliases", 'q', "list_aliases", "--list_aliases"),
        opt("cmd-width", 'c', "cmd_width", "--cmd_width <cmd-width>", false, false),
        opt("tags", 't', "tag", "--tag <tags>...", false, true),
    ],
    subcommands: &[],
    trailing_var_arg: false,
    help_usage: "{bin} list [FLAGS] [OPTIONS]",
};

const MOVE: AppSpec = AppSpec {
    sub_name: Some("move"),
    args: &[
        HELP_FLAG,
        VERSION_FLAG,
        flag("force", 'f', "force", "--force"),
        pos("from-alias", "<from-alias>", true, false),
        pos("to-alias", "<to-alias>", true, false),
    ],
    subcommands: &[],
    trailing_var_arg: false,
    help_usage: "{bin} move [FLAGS] <from-alias> <to-alias>",
};

const REMOVE: AppSpec = AppSpec {
    sub_name: Some("remove"),
    args: &[HELP_FLAG, VERSION_FLAG, pos("alias", "<alias>", true, false)],
    subcommands: &[],
    trailing_var_arg: false,
    help_usage: "{bin} remove <alias>",
};

const RUN: AppSpec = AppSpec {
    sub_name: Some("run"),
    args: &[
        HELP_FLAG,
        VERSION_FLAG,
        pos("alias", "<alias>", true, false),
        pos("args", "<args>...", false, true),
    ],
    subcommands: &[],
    trailing_var_arg: false,
    help_usage: "{bin} run <alias> [args]...",
};

const SHOW: AppSpec = AppSpec {
    sub_name: Some("show"),
    args: &[HELP_FLAG, VERSION_FLAG, pos("alias", "<alias>", true, false)],
    subcommands: &[],
    trailing_var_arg: false,
    help_usage: "{bin} show <alias>",
};

fn spec_for(name: &str) -> Option<&'static AppSpec> {
    Some(match name {
        "add" => &ADD,
        "config-init" => &CONFIG_INIT,
        "copy" => &COPY,
        "edit" => &EDIT,
        "list" => &LIST,
        "move" => &MOVE,
        "remove" => &REMOVE,
        "run" => &RUN,
        "show" => &SHOW,
        _ => return None,
    })
}

/// Resolve a subcommand name or alias to its canonical name.
fn resolve_subcommand(subs: &[SubSpec], word: &str) -> Option<&'static str> {
    subs.iter()
        .find(|s| s.name == word || s.aliases.contains(&word))
        .map(|s| s.name)
}

fn subcommand_names(subs: &'static [SubSpec]) -> impl Iterator<Item = &'static str> {
    subs.iter()
        .map(|s| s.name)
        .chain(subs.iter().flat_map(|s| s.aliases.iter().copied()))
}

// ---------------------------------------------------------------------------
// Colouring of error messages (only when stderr is a terminal)
// ---------------------------------------------------------------------------

struct Painter {
    enabled: bool,
}

impl Painter {
    fn new() -> Self {
        Painter { enabled: std::io::stderr().is_terminal() }
    }
    fn error(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

/// Always green, regardless of the output device.
fn always_good(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}

// ---------------------------------------------------------------------------
// Matcher: what has been seen so far
// ---------------------------------------------------------------------------

#[derive(Default)]
struct Matched {
    occurrences: usize,
    values: Vec<String>,
}

struct Matcher {
    /// Insertion ordered list of (name, matched)
    args: Vec<(&'static str, Matched)>,
}

impl Matcher {
    fn new() -> Self {
        Matcher { args: Vec::new() }
    }
    fn get(&self, name: &str) -> Option<&Matched> {
        self.args.iter().find(|(n, _)| *n == name).map(|(_, m)| m)
    }
    fn entry(&mut self, name: &'static str) -> &mut Matched {
        if let Some(idx) = self.args.iter().position(|(n, _)| *n == name) {
            &mut self.args[idx].1
        } else {
            self.args.push((name, Matched::default()));
            &mut self.args.last_mut().unwrap().1
        }
    }
    fn contains(&self, name: &str) -> bool {
        self.get(name).is_some()
    }
    fn inc(&mut self, name: &'static str) {
        self.entry(name).occurrences += 1;
    }
    fn add_value(&mut self, name: &'static str, value: &str) {
        self.entry(name).values.push(value.to_string());
    }
    fn values(&self, name: &str) -> Vec<String> {
        self.get(name).map(|m| m.values.clone()).unwrap_or_default()
    }
    fn first(&self, name: &str) -> Option<String> {
        self.get(name).and_then(|m| m.values.first().cloned())
    }
}

// ---------------------------------------------------------------------------
// The parser
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq)]
enum Pending {
    None,
    /// Waiting for value(s) of this option.
    Opt(&'static str),
    ValuesDone,
}

struct Parser {
    spec: &'static AppSpec,
    /// Name of the binary as shown in usage strings, e.g. `pier add`.
    bin: String,
    paint: Painter,
}

impl Parser {
    fn usage_bin(&self) -> String {
        self.bin.clone()
    }

    fn find_opt_or_flag_long(&self, long: &str) -> Option<&'static ArgSpec> {
        self.spec
            .args
            .iter()
            .find(|a| a.long == Some(long) && !matches!(a.kind, Kind::Pos { .. }))
    }

    fn find_short(&self, short: char) -> Option<&'static ArgSpec> {
        self.spec
            .args
            .iter()
            .find(|a| a.short == Some(short) && !matches!(a.kind, Kind::Pos { .. }))
    }

    fn positionals(&self) -> Vec<&'static ArgSpec> {
        self.spec
            .args
            .iter()
            .filter(|a| matches!(a.kind, Kind::Pos { .. }))
            .collect()
    }

    fn required_names(&self) -> Vec<&'static str> {
        self.spec.args.iter().filter(|a| a.required).map(|a| a.name).collect()
    }

    /// Full usage as shown in help output.
    fn help_usage(&self) -> String {
        let root_bin = self.bin.split(' ').next().unwrap_or("").to_string();
        self.spec.help_usage.replace("{bin}", &root_bin)
    }

    /// Usage string built from required and already-used arguments.
    fn smart_usage(&self, used: &[&'static str]) -> String {
        let mut names: Vec<&'static str> = self.required_names();
        names.extend_from_slice(used);
        names.sort();
        names.dedup();

        let mut parts: Vec<String> = Vec::new();
        // Positionals first, ordered by their index.
        for p in self.positionals() {
            if names.contains(&p.name) {
                parts.push(p.display.to_string());
            }
        }
        // Then options and flags sorted by name.
        for name in &names {
            if let Some(a) = self.spec.args.iter().find(|a| a.name == *name) {
                if !matches!(a.kind, Kind::Pos { .. }) {
                    parts.push(a.display.to_string());
                }
            }
        }
        let mut usage = self.usage_bin();
        for p in parts {
            usage.push(' ');
            usage.push_str(&p);
        }
        usage
    }

    /// Usage shown in error messages, based on the arguments seen so far.
    fn error_usage(&self, matcher: &Matcher) -> String {
        let used: Vec<&'static str> = matcher
            .args
            .iter()
            .map(|(n, _)| *n)
            .filter(|n| {
                match self.spec.args.iter().find(|a| a.name == *n) {
                    Some(a) => match a.kind {
                        Kind::Opt { .. } => !a.required,
                        Kind::Pos { .. } => false,
                        Kind::Flag => true,
                    },
                    None => true,
                }
            })
            .collect();
        let usage = if used.is_empty() {
            self.help_usage()
        } else {
            self.smart_usage(&used)
        };
        format!("USAGE:\n    {}", usage)
    }

    fn try_help(&self) -> String {
        format!("For more information try {}", self.paint.good("--help"))
    }

    fn err_unknown_argument(&self, arg: &str, suffix: &str, matcher: &Matcher) -> Exit {
        Exit::err(format!(
            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n{}\n\n{}",
            self.paint.error("error:"),
            self.paint.warning(arg),
            if suffix.is_empty() { "\n".to_string() } else { format!("{}\n", suffix) },
            self.error_usage(matcher),
            self.try_help()
        ))
    }

    fn err_invalid_subcommand(&self, word: &str, candidate: &str, matcher: &Matcher) -> Exit {
        Exit::err(format!(
            "{} The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} {} {}'\n\n{}\n\n{}",
            self.paint.error("error:"),
            self.paint.warning(word),
            self.paint.good(candidate),
            self.bin,
            self.paint.good("--"),
            word,
            self.error_usage(matcher),
            self.try_help()
        ))
    }

    fn err_empty_value(&self, arg: &ArgSpec, matcher: &Matcher) -> Exit {
        Exit::err(format!(
            "{} The argument '{}' requires a value but none was supplied\n\n{}\n\n{}",
            self.paint.error("error:"),
            self.paint.warning(arg.display),
            self.error_usage(matcher),
            self.try_help()
        ))
    }

    fn err_multiple_usage(&self, arg: &ArgSpec, matcher: &Matcher) -> Exit {
        Exit::err(format!(
            "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\n{}",
            self.paint.error("error:"),
            self.paint.warning(arg.display),
            self.error_usage(matcher),
            self.try_help()
        ))
    }

    fn err_missing_required(&self, missing: &[&ArgSpec], matcher: &Matcher) -> Exit {
        let mut list = String::new();
        for a in missing {
            list.push_str(&format!("\n    {}", self.paint.error(a.display)));
        }
        Exit::err(format!(
            "{} The following required arguments were not provided:{}\n\n{}\n\n{}",
            self.paint.error("error:"),
            list,
            self.error_usage(matcher),
            self.try_help()
        ))
    }

    fn err_value_validation(&self, arg: &ArgSpec, err: &str) -> Exit {
        Exit::err(format!(
            "{} Invalid value for '{}': {}",
            self.paint.error("error:"),
            self.paint.warning(arg.display),
            err
        ))
    }

    fn help_exit(&self, long: bool) -> Exit {
        let root_bin = self.bin.split(' ').next().unwrap_or("");
        let text = match self.spec.sub_name {
            None => help::main_help(root_bin, long),
            Some(name) => help::subcommand_help(name, root_bin, long).unwrap_or_default(),
        };
        Exit::out(text)
    }

    fn version_exit(&self) -> Exit {
        let root_bin = self.bin.split(' ').next().unwrap_or("");
        let text = match self.spec.sub_name {
            None => help::main_version(root_bin),
            Some(name) => help::subcommand_version(root_bin, name),
        };
        Exit::out(text)
    }

    /// Is `arg` the start of a new argument (as opposed to a value)?
    fn is_new_arg(&self, arg: &str) -> bool {
        if arg.starts_with("--") {
            true
        } else if arg.starts_with('-') {
            arg.len() != 1
        } else {
            false
        }
    }

    fn needs_more_vals(&self, arg: &ArgSpec, matcher: &Matcher) -> bool {
        match arg.kind {
            Kind::Opt { multiple } | Kind::Pos { multiple } => {
                if matcher.get(arg.name).is_some() {
                    multiple
                } else {
                    true
                }
            }
            Kind::Flag => false,
        }
    }

    fn add_val(&self, arg: &'static ArgSpec, val: &str, matcher: &mut Matcher) -> Pending {
        matcher.add_value(arg.name, val);
        if self.needs_more_vals(arg, matcher) {
            Pending::Opt(arg.name)
        } else {
            Pending::ValuesDone
        }
    }

    fn parse_opt(&self, arg: &'static ArgSpec, val: Option<&str>, matcher: &mut Matcher) -> Pending {
        let no_val = val.is_none();
        if let Some(v) = val {
            let v = v.trim_start_matches('=');
            self.add_val(arg, v, matcher);
        }
        matcher.inc(arg.name);
        let multiple = matches!(arg.kind, Kind::Opt { multiple: true });
        if no_val || (multiple && self.needs_more_vals(arg, matcher)) {
            Pending::Opt(arg.name)
        } else {
            Pending::ValuesDone
        }
    }

    fn parse_flag(&self, arg: &'static ArgSpec, matcher: &mut Matcher) -> Result<Pending, Exit> {
        if arg.name == "help" {
            return Err(self.help_exit(false));
        }
        if arg.name == "version" {
            return Err(self.version_exit());
        }
        matcher.inc(arg.name);
        Ok(Pending::None)
    }

    fn parse_long(&self, raw: &str, matcher: &mut Matcher) -> Result<Pending, Exit> {
        let body = &raw[2..];
        let (name, val) = match body.find('=') {
            Some(i) => (&body[..i], Some(&body[i + 1..])),
            None => (body, None),
        };
        if let Some(arg) = self.find_opt_or_flag_long(name) {
            match arg.kind {
                Kind::Opt { .. } => return Ok(self.parse_opt(arg, val, matcher)),
                Kind::Flag => {
                    if arg.name == "help" {
                        return Err(self.help_exit(true));
                    }
                    return self.parse_flag(arg, matcher);
                }
                Kind::Pos { .. } => unreachable!(),
            }
        }
        // Unknown long argument: try to suggest something.
        let longs: Vec<&'static str> = self
            .spec
            .args
            .iter()
            .filter(|a| !matches!(a.kind, Kind::Pos { .. }))
            .filter_map(|a| a.long)
            .collect();
        let suffix = match did_you_mean(name, longs.iter().copied()) {
            Some(candidate) => {
                if let Some(a) = self.find_opt_or_flag_long(candidate) {
                    matcher.entry(a.name);
                }
                format!("\n\tDid you mean {}{}?", always_good("--"), always_good(candidate))
            }
            None => String::new(),
        };
        Err(self.err_unknown_argument(&format!("--{}", name), &suffix, matcher))
    }

    fn parse_short(&self, raw: &str, matcher: &mut Matcher) -> Result<Pending, Exit> {
        let body = &raw[1..];
        let mut ret = Pending::None;
        let mut iter = body.char_indices();
        while let Some((i, c)) = iter.next() {
            if let Some(arg) = self.find_short(c) {
                match arg.kind {
                    Kind::Opt { .. } => {
                        let rest = &body[i + c.len_utf8()..];
                        let val = if rest.is_empty() { None } else { Some(rest) };
                        return Ok(self.parse_opt(arg, val, matcher));
                    }
                    Kind::Flag => {
                        ret = self.parse_flag(arg, matcher)?;
                    }
                    Kind::Pos { .. } => unreachable!(),
                }
            } else {
                let arg = format!("-{}", c);
                return Err(self.err_unknown_argument(&arg, "", matcher));
            }
        }
        Ok(ret)
    }

    /// Parse the given arguments.  Returns the matcher and the name of a
    /// subcommand (plus its remaining arguments) if one was found.
    fn parse(
        &self,
        args: &[String],
    ) -> Result<(Matcher, Option<(&'static str, Vec<String>)>), Exit> {
        let mut matcher = Matcher::new();
        let mut pending = Pending::None;
        let mut trailing = false;
        let positionals = self.positionals();
        let mut pos_counter = 0usize; // index into positionals
        let mut idx = 0usize;

        while idx < args.len() {
            let arg = &args[idx];
            idx += 1;

            let starts_new_arg = match pending {
                Pending::ValuesDone => true,
                _ => self.is_new_arg(arg),
            };

            if !trailing && arg == "--" && starts_new_arg {
                trailing = true;
                continue;
            }

            if !trailing {
                // Subcommand?
                if !matches!(pending, Pending::Opt(_)) {
                    if let Some(sc) = resolve_subcommand(self.spec.subcommands, arg) {
                        if sc == "help" {
                            return Err(self.help_subcommand(&args[idx..]));
                        }
                        return Ok((matcher, Some((sc, args[idx..].to_vec()))));
                    }
                }

                if starts_new_arg {
                    if arg.starts_with("--") {
                        pending = self.parse_long(arg, &mut matcher)?;
                        match pending {
                            Pending::None | Pending::Opt(_) | Pending::ValuesDone => continue,
                        }
                    } else if arg.starts_with('-') && arg.len() != 1 {
                        pending = self.parse_short(arg, &mut matcher)?;
                        continue;
                    }
                } else if let Pending::Opt(name) = pending {
                    let spec = self.spec.args.iter().find(|a| a.name == name).unwrap();
                    pending = self.add_val(spec, arg, &mut matcher);
                    continue;
                }
            }

            // Looks like a misspelled subcommand?
            if !self.spec.subcommands.is_empty() {
                if let Some(candidate) = did_you_mean(arg, subcommand_names(self.spec.subcommands)) {
                    return Err(self.err_invalid_subcommand(arg, candidate, &matcher));
                }
            }

            if let Some(p) = positionals.get(pos_counter) {
                if !trailing && self.trailing_var_arg_hit(pos_counter, positionals.len()) {
                    trailing = true;
                }
                self.add_val(p, arg, &mut matcher);
                matcher.inc(p.name);
                if !matches!(p.kind, Kind::Pos { multiple: true }) {
                    pos_counter += 1;
                }
            } else {
                return Err(self.err_unknown_argument(arg, "", &matcher));
            }
        }

        // Environment provided defaults.
        for a in self.spec.args {
            if let Some(env) = a.env {
                if matcher.get(a.name).map_or(true, |m| m.values.is_empty()) {
                    if let Some(v) = std::env::var_os(env) {
                        matcher.add_value(a.name, &v.to_string_lossy());
                    }
                }
            }
        }

        // Validation.
        if let Pending::Opt(name) = pending {
            let spec = self.spec.args.iter().find(|a| a.name == name).unwrap();
            self.validate_required(&matcher)?;
            let multiple = matches!(spec.kind, Kind::Opt { multiple: true });
            let should_err = match matcher.get(name) {
                Some(m) => m.values.is_empty() && !multiple,
                None => true,
            };
            if should_err {
                return Err(self.err_empty_value(spec, &matcher));
            }
        } else {
            self.validate_required(&matcher)?;
        }
        self.validate_occurrences(&matcher)?;

        Ok((matcher, None))
    }

    fn trailing_var_arg_hit(&self, pos_counter: usize, total: usize) -> bool {
        self.spec.trailing_var_arg && pos_counter + 1 == total
    }

    fn validate_required(&self, matcher: &Matcher) -> Result<(), Exit> {
        let missing: Vec<&ArgSpec> = self
            .spec
            .args
            .iter()
            .filter(|a| a.required && !matcher.contains(a.name))
            .collect();
        if missing.is_empty() {
            return Ok(());
        }
        // Positionals first (by index) then the others sorted by name.
        let mut ordered: Vec<&ArgSpec> = missing
            .iter()
            .copied()
            .filter(|a| matches!(a.kind, Kind::Pos { .. }))
            .collect();
        let mut others: Vec<&ArgSpec> = missing
            .iter()
            .copied()
            .filter(|a| !matches!(a.kind, Kind::Pos { .. }))
            .collect();
        others.sort_by(|a, b| a.name.cmp(b.name));
        ordered.extend(others);
        Err(self.err_missing_required(&ordered, matcher))
    }

    fn validate_occurrences(&self, matcher: &Matcher) -> Result<(), Exit> {
        for (name, m) in &matcher.args {
            if let Some(spec) = self.spec.args.iter().find(|a| a.name == *name) {
                let multiple = matches!(spec.kind, Kind::Opt { multiple: true } | Kind::Pos { multiple: true });
                if m.occurrences > 1 && !multiple {
                    return Err(self.err_multiple_usage(spec, matcher));
                }
            }
        }
        Ok(())
    }

    /// `help [subcommand]...`
    fn help_subcommand(&self, rest: &[String]) -> Exit {
        let root_bin = self.bin.split(' ').next().unwrap_or("").to_string();
        if rest.is_empty() {
            return Exit::out(help::main_help(&root_bin, false));
        }
        let first = &rest[0];
        let Some(sc) = resolve_subcommand(self.spec.subcommands, first) else {
            return self.err_unrecognized_subcommand(first);
        };
        if rest.len() > 1 {
            // Nested subcommands do not exist.
            return self.err_unrecognized_subcommand(&rest[1]);
        }
        Exit::out(help::subcommand_help(sc, &root_bin, false).unwrap_or_default())
    }

    fn err_unrecognized_subcommand(&self, word: &str) -> Exit {
        Exit::err(format!(
            "{} The subcommand '{}' wasn't recognized\n\n{}\n\t{} help <subcommands>...\n\n{}",
            self.paint.error("error:"),
            self.paint.warning(word),
            "USAGE:",
            self.bin,
            self.try_help()
        ))
    }
}

/// Parse the process arguments.
pub fn parse(argv: &[String]) -> Result<Cli, Exit> {
    let bin = argv
        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "pier".to_string());
    let args: Vec<String> = argv.iter().skip(1).cloned().collect();

    let root = Parser { spec: &ROOT, bin: bin.clone(), paint: Painter::new() };
    let (matcher, sub) = root.parse(&args)?;

    let verbose = matcher.contains("verbose");
    let config_file = matcher.first("config-file");

    let command = match sub {
        None => Command::Run {
            alias: matcher.first("alias").unwrap_or_default(),
            args: matcher.values("args"),
        },
        Some((name, rest)) => {
            let spec = spec_for(name).expect("known subcommand");
            let parser = Parser {
                spec,
                bin: format!("{} {}", bin, name),
                paint: Painter::new(),
            };
            let (m, _) = parser.parse(&rest)?;
            build_subcommand(&parser, name, &m)?
        }
    };

    Ok(Cli { verbose, config_file, command })
}

fn build_subcommand(parser: &Parser, name: &str, m: &Matcher) -> Result<Command, Exit> {
    Ok(match name {
        "add" => Command::Add {
            alias: m.first("alias").unwrap_or_default(),
            description: m.first("description"),
            tags: if m.contains("tags") { Some(m.values("tags")) } else { None },
            force: m.contains("force"),
            command: m.first("command"),
        },
        "config-init" => Command::ConfigInit,
        "copy" => Command::Copy {
            from: m.first("from-alias").unwrap_or_default(),
            to: m.first("to-alias").unwrap_or_default(),
        },
        "edit" => Command::Edit { alias: m.first("alias").unwrap_or_default() },
        "list" => {
            let cmd_width = match m.first("cmd-width") {
                Some(v) => {
                    let spec = parser.spec.args.iter().find(|a| a.name == "cmd-width").unwrap();
                    match v.parse::<usize>() {
                        Ok(n) => Some(n),
                        Err(e) => return Err(parser.err_value_validation(spec, &e.to_string())),
                    }
                }
                None => None,
            };
            Command::List {
                list_aliases: m.contains("list-aliases"),
                cmd_full: m.contains("cmd-full"),
                cmd_width,
                tags: if m.contains("tags") { Some(m.values("tags")) } else { None },
            }
        }
        "move" => Command::Move {
            from: m.first("from-alias").unwrap_or_default(),
            to: m.first("to-alias").unwrap_or_default(),
            force: m.contains("force"),
        },
        "remove" => Command::Remove { alias: m.first("alias").unwrap_or_default() },
        "run" => Command::Run {
            alias: m.first("alias").unwrap_or_default(),
            args: m.values("args"),
        },
        "show" => Command::Show { alias: m.first("alias").unwrap_or_default() },
        _ => unreachable!(),
    })
}
