//! Parser producing a generic value tree.

use super::lexer::{LexError, Span, Token, Tokenizer};
use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    String(String),
    Integer(i64),
    Float(f64),
    Boolean(bool),
    Datetime(String),
    Array(Vec<Value>),
    Table(Table),
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct Table {
    /// Entries in document order.  Duplicates are kept so that later stages
    /// can report them.
    pub entries: Vec<(String, Value)>,
    /// Created through a `[header]` (as opposed to an inline/dotted table).
    pub header: bool,
    /// Explicitly defined through a `[header]`.
    pub defined: bool,
}

impl Table {
    pub fn get(&self, key: &str) -> Option<&Value> {
        self.entries.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    }
    fn get_mut(&mut self, key: &str) -> Option<&mut Value> {
        self.entries.iter_mut().find(|(k, _)| k == key).map(|(_, v)| v)
    }
}

impl Value {
    fn same_type(&self, other: &Value) -> bool {
        matches!(
            (self, other),
            (Value::String(..), Value::String(..))
                | (Value::Integer(..), Value::Integer(..))
                | (Value::Float(..), Value::Float(..))
                | (Value::Boolean(..), Value::Boolean(..))
                | (Value::Datetime(..), Value::Datetime(..))
                | (Value::Array(..), Value::Array(..))
                | (Value::Table(..), Value::Table(..))
        )
    }

    /// Description used in "invalid type" messages.
    pub fn unexpected(&self) -> String {
        match self {
            Value::String(s) => format!("string {:?}", s),
            Value::Integer(i) => format!("integer `{}`", i),
            Value::Float(f) => format!("floating point `{}`", f),
            Value::Boolean(b) => format!("boolean `{}`", b),
            Value::Datetime(_) => "map".to_string(),
            Value::Array(_) => "sequence".to_string(),
            Value::Table(_) => "map".to_string(),
        }
    }
}

/// A parse or deserialization error.
#[derive(Debug, Clone)]
pub struct TomlError {
    pub message: String,
    pub key: Vec<String>,
    /// Zero based line.
    pub line: Option<usize>,
}

impl fmt::Display for TomlError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)?;
        if !self.key.is_empty() {
            write!(f, " for key `{}`", self.key.join("."))?;
        }
        if let Some(line) = self.line {
            write!(f, " at line {}", line + 1)?;
        }
        Ok(())
    }
}

impl TomlError {
    pub fn custom(message: String) -> Self {
        TomlError { message, key: Vec::new(), line: None }
    }
    pub fn with_key(mut self, key: &str) -> Self {
        self.key.insert(0, key.to_string());
        self
    }
}

struct RawTable {
    at: usize,
    header: Vec<String>,
    array: bool,
    values: Vec<(String, Value)>,
}

struct Parser<'a> {
    tokens: Tokenizer<'a>,
    input: &'a str,
}

type PResult<T> = Result<T, (usize, String)>;

fn lex_err(e: LexError) -> (usize, String) {
    match e {
        LexError::InvalidCharInString(at, c) => {
            (at, format!("invalid character in string: `{}`", c.escape_default()))
        }
        LexError::InvalidEscape(at, c) => {
            (at, format!("invalid escape character in string: `{}`", c.escape_default()))
        }
        LexError::InvalidHexEscape(at, c) => {
            (at, format!("invalid hex escape character in string: `{}`", c.escape_default()))
        }
        LexError::InvalidEscapeValue(at, v) => (at, format!("invalid escape value: `{}`", v)),
        LexError::NewlineInString(at) => (at, "newline in string found".to_string()),
        LexError::Unexpected(at, c) => {
            (at, format!("unexpected character found: `{}`", c.escape_default()))
        }
        LexError::UnterminatedString(at) => (at, "unterminated string".to_string()),
        LexError::NewlineInTableKey(at) => (at, "found newline in table key".to_string()),
        LexError::MultilineStringKey(at) => {
            (at, "multiline strings are not allowed for key".to_string())
        }
        LexError::EmptyTableKey(at) => (at, "empty table key found".to_string()),
        LexError::Wanted { at, expected, found } => {
            (at, format!("expected {}, found {}", expected, found))
        }
    }
}

trait LexResultExt<T> {
    fn lex(self) -> PResult<T>;
}

impl<T> LexResultExt<T> for Result<T, LexError> {
    fn lex(self) -> PResult<T> {
        self.map_err(lex_err)
    }
}

enum Line {
    Table { at: usize, header: Vec<String>, array: bool },
    KeyValue(Vec<String>, Value),
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { tokens: Tokenizer::new(input), input }
    }

    fn eof(&mut self) -> (usize, String) {
        (self.input.len(), "unexpected eof encountered".to_string())
    }

    fn tables(&mut self) -> PResult<Vec<RawTable>> {
        let mut tables = Vec::new();
        let mut cur_table = RawTable { at: 0, header: Vec::new(), array: false, values: Vec::new() };
        let mut cur_has_values = false;

        while let Some(line) = self.line()? {
            match line {
                Line::Table { at, header, array } => {
                    if !cur_table.header.is_empty() || cur_has_values {
                        tables.push(cur_table);
                    }
                    cur_table = RawTable { at, header, array, values: Vec::new() };
                    cur_has_values = true;
                }
                Line::KeyValue(key, value) => {
                    cur_has_values = true;
                    self.add_dotted_key(key, value, &mut cur_table.values)?;
                }
            }
        }
        if !cur_table.header.is_empty() || cur_has_values {
            tables.push(cur_table);
        }
        Ok(tables)
    }

    fn line(&mut self) -> PResult<Option<Line>> {
        loop {
            self.tokens.eat_whitespace().lex()?;
            if self.tokens.eat_comment().lex()? {
                continue;
            }
            if self.tokens.eat(Token::Newline).lex()? {
                continue;
            }
            break;
        }
        match self.tokens.peek().lex()? {
            Some((_, Token::LeftBracket)) => self.table_header().map(Some),
            Some(_) => self.key_value().map(Some),
            None => Ok(None),
        }
    }

    fn table_header(&mut self) -> PResult<Line> {
        let start = self.tokens.current();
        self.tokens.expect(Token::LeftBracket).lex()?;
        let array = self.tokens.eat(Token::LeftBracket).lex()?;
        let mut header = Vec::new();
        let mut first = true;
        loop {
            self.tokens.eat_whitespace().lex()?;
            if first || self.tokens.eat(Token::Period).lex()? {
                first = false;
                self.tokens.eat_whitespace().lex()?;
                let (_, key) = self.tokens.table_key().lex()?;
                header.push(key.into_owned());
            } else {
                self.tokens.expect(Token::RightBracket).lex()?;
                if array {
                    self.tokens.expect(Token::RightBracket).lex()?;
                }
                self.tokens.eat_whitespace().lex()?;
                if !self.tokens.eat_comment().lex()? {
                    self.tokens.eat_newline_or_eof().lex()?;
                }
                break;
            }
        }
        Ok(Line::Table { at: start, header, array })
    }

    fn key_value(&mut self) -> PResult<Line> {
        let key = self.dotted_key()?;
        self.tokens.eat_whitespace().lex()?;
        self.tokens.expect(Token::Equals).lex()?;
        self.tokens.eat_whitespace().lex()?;

        let value = self.value()?;
        self.tokens.eat_whitespace().lex()?;
        if !self.tokens.eat_comment().lex()? {
            self.tokens.eat_newline_or_eof().lex()?;
        }
        Ok(Line::KeyValue(key, value))
    }

    fn dotted_key(&mut self) -> PResult<Vec<String>> {
        let mut result = Vec::new();
        result.push(self.tokens.table_key().lex()?.1.into_owned());
        self.tokens.eat_whitespace().lex()?;
        while self.tokens.eat(Token::Period).lex()? {
            self.tokens.eat_whitespace().lex()?;
            result.push(self.tokens.table_key().lex()?.1.into_owned());
            self.tokens.eat_whitespace().lex()?;
        }
        Ok(result)
    }

    fn value(&mut self) -> PResult<Value> {
        let at = self.tokens.current();
        let value = match self.tokens.next().lex()? {
            Some((_, Token::String { val, .. })) => Value::String(val.into_owned()),
            Some((_, Token::Keylike("true"))) => Value::Boolean(true),
            Some((_, Token::Keylike("false"))) => Value::Boolean(false),
            Some((span, Token::Keylike(key))) => self.number_or_date(span, key)?,
            Some((span, Token::Plus)) => self.number_leading_plus(span)?,
            Some((_, Token::LeftBrace)) => Value::Table(self.inline_table()?),
            Some((_, Token::LeftBracket)) => Value::Array(self.array()?),
            Some((_, token)) => {
                return Err((at, format!("expected a value, found {}", token.describe())))
            }
            None => return Err(self.eof()),
        };
        Ok(value)
    }

    fn number_or_date(&mut self, span: Span, s: &'a str) -> PResult<Value> {
        if s.contains('T')
            || s.contains('t')
            || (s.len() > 1 && s[1..].contains('-') && !s.contains("e-") && !s.contains("E-"))
        {
            self.datetime(span, s, false)
        } else if self.tokens.eat(Token::Colon).lex()? {
            self.datetime(span, s, true)
        } else {
            self.number(span, s)
        }
    }

    fn number_leading_plus(&mut self, span: Span) -> PResult<Value> {
        let start_token = self.tokens.current();
        match self.tokens.next().lex()? {
            Some((_, Token::Keylike(s))) => self.number(span, s),
            _ => Err((start_token, "invalid number".to_string())),
        }
    }

    fn number(&mut self, span: Span, s: &'a str) -> PResult<Value> {
        let at = span.start;
        if let Some(rest) = s.strip_prefix("0x") {
            self.integer(at, rest, 16).map(Value::Integer)
        } else if let Some(rest) = s.strip_prefix("0o") {
            self.integer(at, rest, 8).map(Value::Integer)
        } else if let Some(rest) = s.strip_prefix("0b") {
            self.integer(at, rest, 2).map(Value::Integer)
        } else if s.contains('e') || s.contains('E') {
            self.float(at, s, None).map(Value::Float)
        } else if self.tokens.eat(Token::Period).lex()? {
            let at2 = self.tokens.current();
            match self.tokens.next().lex()? {
                Some((_, Token::Keylike(after))) => self.float(at, s, Some(after)).map(Value::Float),
                _ => Err((at2, "invalid number".to_string())),
            }
        } else if s == "inf" {
            Ok(Value::Float(f64::INFINITY))
        } else if s == "-inf" {
            Ok(Value::Float(f64::NEG_INFINITY))
        } else if s == "nan" || s == "-nan" {
            Ok(Value::Float(f64::NAN))
        } else {
            self.integer(at, s, 10).map(Value::Integer)
        }
    }

    fn integer(&self, at: usize, s: &'a str, radix: u32) -> PResult<i64> {
        let allow_sign = radix == 10;
        let allow_leading_zeros = radix != 10;
        let (prefix, suffix) = self.parse_integer(at, s, allow_sign, allow_leading_zeros, radix)?;
        if !suffix.is_empty() {
            return Err((at, "invalid number".to_string()));
        }
        i64::from_str_radix(&prefix.replace('_', "").trim_start_matches('+'), radix)
            .map_err(|_| (at, "invalid number".to_string()))
    }

    fn parse_integer(
        &self,
        at: usize,
        s: &'a str,
        allow_sign: bool,
        allow_leading_zeros: bool,
        radix: u32,
    ) -> PResult<(&'a str, &'a str)> {
        let start = self.tokens.current();
        let _ = start;
        let mut first = true;
        let mut first_zero = false;
        let mut underscore = false;
        let mut end = s.len();
        for (i, c) in s.char_indices() {
            let at_c = at + i;
            let _ = at_c;
            if i == 0 && (c == '+' || c == '-') && allow_sign {
                continue;
            }
            if c == '0' && first {
                first_zero = true;
            } else if c.is_digit(radix) {
                if !first && first_zero && !allow_leading_zeros {
                    return Err((at, "invalid number".to_string()));
                }
                underscore = false;
            } else if c == '_' && first {
                return Err((at, "invalid number".to_string()));
            } else if c == '_' && !underscore {
                underscore = true;
            } else {
                end = i;
                break;
            }
            first = false;
        }
        if first || underscore {
            return Err((at, "invalid number".to_string()));
        }
        Ok((&s[..end], &s[end..]))
    }

    fn float(&mut self, at: usize, s: &'a str, after_decimal: Option<&'a str>) -> PResult<f64> {
        let (integral, mut suffix) = self.parse_integer(at, s, true, false, 10)?;
        let mut fraction = None;
        if let Some(after) = after_decimal {
            if !suffix.is_empty() {
                return Err((at, "invalid number".to_string()));
            }
            let (a, b) = self.parse_integer(at, after, false, true, 10)?;
            fraction = Some(a);
            suffix = b;
        }

        let mut exponent = None;
        if suffix.starts_with('e') || suffix.starts_with('E') {
            let (a, b) = if suffix.len() == 1 {
                self.tokens.eat(Token::Plus).lex()?;
                match self.tokens.next().lex()? {
                    Some((_, Token::Keylike(s))) => self.parse_integer(at, s, false, false, 10)?,
                    _ => return Err((at, "invalid number".to_string())),
                }
            } else {
                self.parse_integer(at, &suffix[1..], true, false, 10)?
            };
            if !b.is_empty() {
                return Err((at, "invalid number".to_string()));
            }
            exponent = Some(a);
        } else if !suffix.is_empty() {
            return Err((at, "invalid number".to_string()));
        }

        let mut number = integral.trim_start_matches('+').replace('_', "");
        if let Some(fraction) = fraction {
            number.push('.');
            number.push_str(&fraction.replace('_', ""));
        }
        if let Some(exponent) = exponent {
            number.push('E');
            number.push_str(&exponent.replace('_', ""));
        }
        number
            .parse::<f64>()
            .map_err(|_| (at, "invalid number".to_string()))
            .and_then(|n| if n.is_finite() { Ok(n) } else { Err((at, "invalid number".to_string())) })
    }

    /// Dates are kept as their textual representation.
    fn datetime(&mut self, span: Span, date: &'a str, colon_eaten: bool) -> PResult<Value> {
        let start = span.start;
        let mut end = span.end;
        let invalid = |at: usize| (at, "invalid date".to_string());

        // Validate roughly: digits, '-', ':', 'T', 't', 'Z', 'z', '.', '+' are the only
        // acceptable characters.
        let ok = |s: &str| {
            s.chars().all(|c| c.is_ascii_digit() || matches!(c, '-' | ':' | 'T' | 't' | 'Z' | 'z' | '.' | '+'))
        };
        if !ok(date) {
            return Err(invalid(start));
        }

        if colon_eaten || date.ends_with('T') || date.ends_with('t') {
            // Time portion after the colon or 'T'.
            match self.tokens.next().lex()? {
                Some((s, Token::Keylike(k))) if ok(k) => end = s.end,
                _ => return Err(invalid(start)),
            }
            // Possibly fractional seconds / offsets.
            loop {
                let mut t = self.tokens.clone();
                match t.next().lex()? {
                    Some((s, Token::Colon)) | Some((s, Token::Period)) | Some((s, Token::Plus)) => {
                        self.tokens = t;
                        end = s.end;
                        match self.tokens.next().lex()? {
                            Some((s2, Token::Keylike(k))) if ok(k) => end = s2.end,
                            _ => return Err(invalid(start)),
                        }
                    }
                    _ => break,
                }
            }
        } else if date.contains('T') || date.contains('t') {
            // A combined date-time; there may be a fractional/offset part.
            loop {
                let mut t = self.tokens.clone();
                match t.next().lex()? {
                    Some((s, Token::Colon)) | Some((s, Token::Period)) | Some((s, Token::Plus)) => {
                        self.tokens = t;
                        end = s.end;
                        match self.tokens.next().lex()? {
                            Some((s2, Token::Keylike(k))) if ok(k) => end = s2.end,
                            _ => return Err(invalid(start)),
                        }
                    }
                    _ => break,
                }
            }
        } else {
            // Local date possibly followed by whitespace and a time.
            let mut t = self.tokens.clone();
            if let Ok(Some((_, Token::Whitespace(_)))) = t.next() {
                if let Ok(Some((s, Token::Keylike(k)))) = t.next() {
                    if k.len() >= 2 && k.chars().all(|c| c.is_ascii_digit()) {
                        if let Ok(true) = t.eat(Token::Colon) {
                            self.tokens = t;
                            end = s.end;
                            match self.tokens.next().lex()? {
                                Some((s2, Token::Keylike(k2))) if ok(k2) => end = s2.end,
                                _ => return Err(invalid(start)),
                            }
                            loop {
                                let mut t2 = self.tokens.clone();
                                match t2.next().lex()? {
                                    Some((s3, Token::Colon)) | Some((s3, Token::Period)) => {
                                        self.tokens = t2;
                                        end = s3.end;
                                        match self.tokens.next().lex()? {
                                            Some((s4, Token::Keylike(k3))) if ok(k3) => end = s4.end,
                                            _ => return Err(invalid(start)),
                                        }
                                    }
                                    _ => break,
                                }
                            }
                        }
                    }
                }
            }
        }
        Ok(Value::Datetime(self.input[start..end.min(self.input.len())].to_string()))
    }

    fn array(&mut self) -> PResult<Vec<Value>> {
        let mut ret = Vec::new();
        loop {
            self.intermediate()?;
            if self.tokens.eat(Token::RightBracket).lex()? {
                return Ok(ret);
            }
            let at = self.tokens.current();
            let value = self.value()?;
            if let Some(last) = ret.last() {
                if !value.same_type(last) {
                    return Err((at, "mixed types in an array".to_string()));
                }
            }
            ret.push(value);
            self.intermediate()?;
            if !self.tokens.eat(Token::Comma).lex()? {
                break;
            }
        }
        self.intermediate()?;
        self.tokens.expect(Token::RightBracket).lex()?;
        Ok(ret)
    }

    fn intermediate(&mut self) -> PResult<()> {
        loop {
            self.tokens.eat_whitespace().lex()?;
            if !self.tokens.eat(Token::Newline).lex()? && !self.tokens.eat_comment().lex()? {
                break;
            }
        }
        Ok(())
    }

    fn inline_table(&mut self) -> PResult<Table> {
        let mut ret: Vec<(String, Value)> = Vec::new();
        self.tokens.eat_whitespace().lex()?;
        if self.tokens.eat(Token::RightBrace).lex()? {
            return Ok(Table { entries: ret, header: false, defined: true });
        }
        loop {
            let key = self.dotted_key()?;
            self.tokens.eat_whitespace().lex()?;
            self.tokens.expect(Token::Equals).lex()?;
            self.tokens.eat_whitespace().lex()?;
            let value = self.value()?;
            self.add_dotted_key(key, value, &mut ret)?;

            self.tokens.eat_whitespace().lex()?;
            if self.tokens.eat(Token::RightBrace).lex()? {
                return Ok(Table { entries: ret, header: false, defined: true });
            }
            self.tokens.expect(Token::Comma).lex()?;
            self.tokens.eat_whitespace().lex()?;
        }
    }

    fn add_dotted_key(
        &self,
        mut key_parts: Vec<String>,
        value: Value,
        values: &mut Vec<(String, Value)>,
    ) -> PResult<()> {
        let key = key_parts.remove(0);
        if key_parts.is_empty() {
            values.push((key, value));
            return Ok(());
        }
        let at = self.tokens.clone().current();
        if let Some(existing) = values.iter_mut().find(|(k, _)| *k == key) {
            return match &mut existing.1 {
                Value::Table(t) if !t.header => self.add_dotted_key(key_parts, value, &mut t.entries),
                _ => Err((at, "dotted key attempted to extend non-table type".to_string())),
            };
        }
        let mut table = Table { entries: Vec::new(), header: false, defined: true };
        self.add_dotted_key(key_parts, value, &mut table.entries)?;
        values.push((key, Value::Table(table)));
        Ok(())
    }

    fn to_line(&self, offset: usize) -> usize {
        let mut cur = 0;
        for (i, line) in self.input.lines().enumerate() {
            if cur + line.len() + 1 > offset {
                return i;
            }
            cur += line.len() + 1;
        }
        self.input.lines().count()
    }
}

/// Parse a document into its root table.
pub fn parse(input: &str) -> Result<Table, TomlError> {
    let mut parser = Parser::new(input);
    let tables = match parser.tables() {
        Ok(t) => t,
        Err((at, message)) => {
            return Err(TomlError { message, key: Vec::new(), line: Some(parser.to_line(at)) })
        }
    };

    let mut root = Table { entries: Vec::new(), header: true, defined: true };
    for table in tables {
        if table.header.is_empty() {
            root.entries.extend(table.values);
            continue;
        }
        let path = table.header.clone();
        let line = parser.to_line(table.at);
        let dup = |msg: String| TomlError { message: msg, key: path.clone(), line: Some(line) };

        let mut cur: &mut Table = &mut root;
        let last_idx = table.header.len() - 1;
        for (i, part) in table.header.iter().enumerate() {
            let last = i == last_idx;
            let exists = cur.get(part).is_some();
            if !exists {
                if last && table.array {
                    let mut t = Table { entries: table.values.clone(), header: true, defined: true };
                    t.entries = table.values.clone();
                    cur.entries.push((part.clone(), Value::Array(vec![Value::Table(t)])));
                    break;
                }
                cur.entries.push((
                    part.clone(),
                    Value::Table(Table { entries: Vec::new(), header: true, defined: last }),
                ));
            }
            let entry = cur.get_mut(part).unwrap();
            match entry {
                Value::Table(t) => {
                    if last {
                        if table.array {
                            return Err(dup("table redefined as array".to_string()));
                        }
                        if t.defined && exists {
                            return Err(dup(format!("redefinition of table `{}`", path.join("."))));
                        }
                        t.defined = true;
                        t.header = true;
                        t.entries.extend(table.values.clone());
                        break;
                    }
                    cur = t;
                }
                Value::Array(items) => {
                    if last {
                        if !table.array {
                            return Err(dup(format!("redefinition of table `{}`", path.join("."))));
                        }
                        let t = Table { entries: table.values.clone(), header: true, defined: true };
                        items.push(Value::Table(t));
                        break;
                    }
                    match items.last_mut() {
                        Some(Value::Table(t)) => cur = t,
                        _ => return Err(dup(format!("redefinition of table `{}`", path.join(".")))),
                    }
                }
                _ => {
                    return Err(dup("dotted key attempted to extend non-table type".to_string()));
                }
            }
        }
    }
    Ok(root)
}
