//! Helpers to turn a parsed value tree into typed data, with error messages
//! in the style of serde ("invalid type: integer `1`, expected a string").

pub use super::parser::TomlError as DeError;
use super::parser::{Table, Value};

/// Convenience wrapper offering typed accessors.
pub struct Deserializer;

impl Deserializer {
    pub fn invalid_type(value: &Value, expected: &str) -> DeError {
        DeError::custom(format!("invalid type: {}, expected {}", value.unexpected(), expected))
    }

    pub fn string(value: &Value) -> Result<String, DeError> {
        match value {
            Value::String(s) => Ok(s.clone()),
            other => Err(Self::invalid_type(other, "a string")),
        }
    }

    pub fn usize(value: &Value) -> Result<usize, DeError> {
        match value {
            Value::Integer(i) => {
                if *i < 0 {
                    Err(DeError::custom(format!("invalid value: integer `{}`, expected usize", i)))
                } else {
                    Ok(*i as usize)
                }
            }
            other => Err(Self::invalid_type(other, "usize")),
        }
    }

    pub fn string_seq(value: &Value) -> Result<Vec<String>, DeError> {
        match value {
            Value::Array(items) => items.iter().map(Self::string).collect(),
            other => Err(Self::invalid_type(other, "a sequence")),
        }
    }

    /// Deserialize a struct-like value.  `fields` lists the field names in
    /// declaration order; `set` is invoked for every known field with its
    /// value and must report errors.  Unknown fields are ignored, duplicate
    /// fields are rejected.  Returns the set of fields that were provided.
    pub fn struct_fields<F>(
        value: &Value,
        name: &str,
        fields: &[&str],
        mut set: F,
    ) -> Result<Vec<bool>, DeError>
    where
        F: FnMut(usize, &Value) -> Result<(), DeError>,
    {
        let mut seen = vec![false; fields.len()];
        match value {
            Value::Table(table) => {
                for (key, val) in &table.entries {
                    if let Some(idx) = fields.iter().position(|f| f == key) {
                        if seen[idx] {
                            return Err(DeError::custom(format!("duplicate field `{}`", key)));
                        }
                        seen[idx] = true;
                        let res = set(idx, val);
                        if let Err(e) = res {
                            return Err(if table.header { e.with_key(key) } else { e });
                        }
                    }
                }
                Ok(seen)
            }
            Value::Array(items) => {
                let mut it = items.iter();
                for (idx, _) in fields.iter().enumerate() {
                    match it.next() {
                        Some(val) => {
                            seen[idx] = true;
                            set(idx, val)?;
                        }
                        None => {
                            return Err(DeError::custom(format!(
                                "invalid length {}, expected struct {} with {} elements",
                                items.len(),
                                name,
                                fields.len()
                            )))
                        }
                    }
                }
                Ok(seen)
            }
            other => Err(Self::invalid_type(other, &format!("struct {}", name))),
        }
    }

    /// Iterate over the entries of a map-like value.
    pub fn map<F>(value: &Value, expected: &str, mut each: F) -> Result<(), DeError>
    where
        F: FnMut(&str, &Value) -> Result<(), DeError>,
    {
        match value {
            Value::Table(table) => {
                for (key, val) in &table.entries {
                    let res = each(key, val);
                    if let Err(e) = res {
                        return Err(if table.header { e.with_key(key) } else { e });
                    }
                }
                Ok(())
            }
            other => Err(Self::invalid_type(other, expected)),
        }
    }

    pub fn missing_field(name: &str) -> DeError {
        DeError::custom(format!("missing field `{}`", name))
    }
}

/// Access to the root table entries with key context handling.
pub fn root_entries(root: &Table) -> &[(String, Value)] {
    &root.entries
}
