//! Writer producing the "pretty" TOML layout.

use std::fmt::Write;

/// A value to be written.
pub enum Out {
    Str(String),
    Int(i64),
    /// Array of strings.
    StrArray(Vec<String>),
}

/// A table consisting of simple key/value pairs.
pub struct OutTable {
    pub path: Vec<String>,
    pub entries: Vec<(String, Out)>,
}

fn escape_key(key: &str, dst: &mut String) {
    let bare = key.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_');
    if bare {
        dst.push_str(key);
    } else {
        emit_std_string(key, false, dst);
    }
}

fn emit_std_string(value: &str, multiline: bool, dst: &mut String) {
    if multiline {
        dst.push_str("\"\"\"\n");
    } else {
        dst.push('"');
    }
    for ch in value.chars() {
        match ch {
            '\u{8}' => dst.push_str("\\b"),
            '\u{9}' => dst.push_str("\\t"),
            '\u{a}' => {
                if multiline {
                    dst.push('\n')
                } else {
                    dst.push_str("\\n")
                }
            }
            '\u{c}' => dst.push_str("\\f"),
            '\u{d}' => dst.push_str("\\r"),
            '\u{22}' => dst.push_str("\\\""),
            '\u{5c}' => dst.push_str("\\\\"),
            c if c <= '\u{1f}' || c == '\u{7f}' => {
                let _ = write!(dst, "\\u{:04X}", c as u32);
            }
            c => dst.push(c),
        }
    }
    if multiline {
        dst.push_str("\"\"\"");
    } else {
        dst.push('"');
    }
}

/// Emit a string value, preferring literal strings when possible.
fn emit_str(value: &str, dst: &mut String) {
    #[derive(PartialEq)]
    enum Ty {
        NewlineTriple,
        OnelineTriple,
        OnelineSingle,
    }

    let mut ty = Ty::OnelineSingle;
    let mut max_found_singles = 0;
    let mut found_singles = 0;
    let mut can_be_pretty = true;

    for ch in value.chars() {
        if can_be_pretty {
            if ch == '\'' {
                found_singles += 1;
                if found_singles >= 3 {
                    can_be_pretty = false;
                }
            } else {
                if found_singles > max_found_singles {
                    max_found_singles = found_singles;
                }
                found_singles = 0;
            }
            match ch {
                '\t' => {}
                '\n' => ty = Ty::NewlineTriple,
                c if c <= '\u{1f}' || c == '\u{7f}' => can_be_pretty = false,
                _ => {}
            }
        } else if ch == '\n' {
            ty = Ty::NewlineTriple;
        }
    }
    if can_be_pretty && found_singles > 0 && value.ends_with('\'') {
        can_be_pretty = false;
    }
    if !can_be_pretty {
        emit_std_string(value, ty == Ty::NewlineTriple, dst);
        return;
    }
    if found_singles > max_found_singles {
        max_found_singles = found_singles;
    }
    if ty == Ty::OnelineSingle && max_found_singles >= 1 {
        ty = Ty::OnelineTriple;
    }
    match ty {
        Ty::NewlineTriple => dst.push_str("'''\n"),
        Ty::OnelineTriple => dst.push_str("'''"),
        Ty::OnelineSingle => dst.push('\''),
    }
    dst.push_str(value);
    match ty {
        Ty::OnelineSingle => dst.push('\''),
        _ => dst.push_str("'''"),
    }
}

fn emit_value(value: &Out, dst: &mut String) {
    match value {
        Out::Str(s) => emit_str(s, dst),
        Out::Int(i) => {
            let _ = write!(dst, "{}", i);
        }
        Out::StrArray(items) => {
            if items.len() <= 1 {
                dst.push('[');
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        dst.push_str(", ");
                    }
                    emit_str(item, dst);
                }
                dst.push(']');
            } else {
                dst.push_str("[\n");
                for item in items {
                    dst.push_str("    ");
                    emit_str(item, dst);
                    dst.push_str(",\n");
                }
                dst.push(']');
            }
        }
    }
}

/// Serialize a sequence of tables.  Every table gets a header, the first
/// one is not preceded by a blank line.
pub fn to_string(tables: &[OutTable]) -> String {
    let mut dst = String::new();
    for (i, table) in tables.iter().enumerate() {
        if i > 0 {
            dst.push('\n');
        }
        dst.push('[');
        for (j, part) in table.path.iter().enumerate() {
            if j > 0 {
                dst.push('.');
            }
            escape_key(part, &mut dst);
        }
        dst.push_str("]\n");
        for (key, value) in &table.entries {
            escape_key(key, &mut dst);
            dst.push_str(" = ");
            emit_value(value, &mut dst);
            dst.push('\n');
        }
    }
    dst
}
