//! Configuration file handling: discovery, reading, writing.

use crate::error::PierError;
use crate::toml::ser::{to_string, Out, OutTable};
use crate::toml::{parse, Deserializer, Value};
use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Default, PartialEq)]
pub struct Script {
    pub command: String,
    pub description: Option<String>,
    pub reference: Option<String>,
    pub tags: Option<Vec<String>>,
}

#[derive(Debug, Clone, Default)]
pub struct DefaultOpts {
    pub interpreter: Option<Vec<String>>,
    pub command_width: Option<usize>,
}

#[derive(Debug, Clone, Default)]
pub struct Config {
    pub scripts: Option<BTreeMap<String, Script>>,
    pub default: DefaultOpts,
}

impl Script {
    fn from_value(value: &Value) -> Result<Script, crate::toml::DeError> {
        const FIELDS: &[&str] = &["command", "description", "reference", "tags"];
        let mut script = Script::default();
        let seen = Deserializer::struct_fields(value, "Script", FIELDS, |idx, v| {
            match idx {
                0 => script.command = Deserializer::string(v)?,
                1 => script.description = Some(Deserializer::string(v)?),
                2 => script.reference = Some(Deserializer::string(v)?),
                _ => script.tags = Some(Deserializer::string_seq(v)?),
            }
            Ok(())
        })?;
        if !seen[0] {
            return Err(Deserializer::missing_field("command"));
        }
        Ok(script)
    }
}

impl DefaultOpts {
    fn from_value(value: &Value) -> Result<DefaultOpts, crate::toml::DeError> {
        const FIELDS: &[&str] = &["interpreter", "command_width"];
        let mut opts = DefaultOpts::default();
        Deserializer::struct_fields(value, "ConfigDefaultOpts", FIELDS, |idx, v| {
            match idx {
                0 => opts.interpreter = Some(Deserializer::string_seq(v)?),
                _ => opts.command_width = Some(Deserializer::usize(v)?),
            }
            Ok(())
        })?;
        Ok(opts)
    }
}

impl Config {
    /// Parse a configuration document.
    pub fn from_str(input: &str) -> Result<Config, crate::toml::DeError> {
        let root = parse(input)?;
        let mut config = Config::default();
        let mut seen_scripts = false;
        let mut seen_default = false;
        for (key, value) in &root.entries {
            match key.as_str() {
                "scripts" => {
                    if seen_scripts {
                        return Err(crate::toml::DeError::custom("duplicate field `scripts`".to_string()));
                    }
                    seen_scripts = true;
                    let mut map = BTreeMap::new();
                    Deserializer::map(value, "map is expected", |k, v| {
                        let script = Script::from_value(v)?;
                        map.insert(k.to_string(), script);
                        Ok(())
                    })
                    .map_err(|e| e.with_key(key))?;
                    config.scripts = Some(map);
                }
                "default" => {
                    if seen_default {
                        return Err(crate::toml::DeError::custom("duplicate field `default`".to_string()));
                    }
                    seen_default = true;
                    config.default = DefaultOpts::from_value(value).map_err(|e| e.with_key(key))?;
                }
                _ => {}
            }
        }
        Ok(config)
    }

    /// Serialize the configuration.
    pub fn to_toml(&self) -> String {
        let mut tables = Vec::new();
        if let Some(scripts) = &self.scripts {
            for (alias, script) in scripts {
                let mut entries = vec![("command".to_string(), Out::Str(script.command.clone()))];
                if let Some(d) = &script.description {
                    entries.push(("description".to_string(), Out::Str(d.clone())));
                }
                if let Some(r) = &script.reference {
                    entries.push(("reference".to_string(), Out::Str(r.clone())));
                }
                if let Some(t) = &script.tags {
                    entries.push(("tags".to_string(), Out::StrArray(t.clone())));
                }
                tables.push(OutTable { path: vec!["scripts".to_string(), alias.clone()], entries });
            }
        }
        let mut entries = Vec::new();
        if let Some(i) = &self.default.interpreter {
            entries.push(("interpreter".to_string(), Out::StrArray(i.clone())));
        }
        if let Some(w) = self.default.command_width {
            entries.push(("command_width".to_string(), Out::Int(w as i64)));
        }
        tables.push(OutTable { path: vec!["default".to_string()], entries });
        to_string(&tables)
    }

    /// Read and parse the configuration at `path`.
    pub fn load(path: &Path) -> Result<Config, PierError> {
        let text = fs::read_to_string(path).map_err(|e| PierError::ConfigRead {
            path: path.to_string_lossy().into_owned(),
            source: e.to_string(),
        })?;
        Config::from_str(&text).map_err(|e| PierError::ConfigParse {
            path: path.to_string_lossy().into_owned(),
            source: e.to_string(),
        })
    }

    /// Write the configuration to `path`.
    pub fn write(&self, path: &Path) -> Result<(), PierError> {
        fs::write(path, self.to_toml()).map_err(|e| PierError::ConfigWrite {
            path: path.to_string_lossy().into_owned(),
            source: e.to_string(),
        })
    }

    /// Example configuration created by `config-init`.
    pub fn example() -> Config {
        let mut scripts = BTreeMap::new();
        scripts.insert(
            "hello-pier".to_string(),
            Script {
                command: "echo Hello, Pier!".to_string(),
                description: Some("This is an example command.".to_string()),
                reference: None,
                tags: None,
            },
        );
        Config { scripts: Some(scripts), default: DefaultOpts::default() }
    }
}

/// Home directory as determined by `$HOME`, falling back to the password
/// database.
pub fn home_dir() -> Option<PathBuf> {
    if let Some(h) = std::env::var_os("HOME") {
        if !h.is_empty() {
            return Some(PathBuf::from(h));
        }
    }
    crate::sys::passwd_home_dir()
}

/// `$XDG_CONFIG_HOME` (if absolute) or `$HOME/.config`.
pub fn config_dir() -> Option<PathBuf> {
    if let Some(x) = std::env::var_os("XDG_CONFIG_HOME") {
        let p = PathBuf::from(x);
        if p.is_absolute() {
            return Some(p);
        }
    }
    home_dir().map(|h| h.join(".config"))
}

/// Locate the default configuration file, if any exists.
pub fn find_default_config() -> Option<PathBuf> {
    let mut candidates: Vec<PathBuf> = Vec::new();
    if let Some(env) = std::env::var_os("PIER_CONFIG_PATH") {
        candidates.push(PathBuf::from(env));
    }
    candidates.push(PathBuf::from("pier.toml"));
    if let Some(cfg) = config_dir() {
        candidates.push(cfg.join("pier").join("config.toml"));
        candidates.push(cfg.join("pier").join("config"));
        candidates.push(cfg.join("pier.toml"));
    }
    if let Some(home) = home_dir() {
        candidates.push(home.join(".pier.toml"));
        candidates.push(home.join(".pier"));
    }
    candidates.into_iter().find(|p| p.exists())
}

/// Path used by `config-init` when nothing exists yet.
pub fn default_init_path() -> Option<PathBuf> {
    config_dir().map(|c| c.join("pier").join("config.toml"))
}
