//! Error type shared across the application.

use std::fmt;

#[derive(Debug)]
pub enum PierError {
    NoConfigFile,
    ConfigRead { path: String, source: String },
    ConfigParse { path: String, source: String },
    ConfigWrite { path: String, source: String },
    ConfigInitExists { path: String },
    CreateDirectory { source: String },
    NoScriptsExists,
    AliasNotFound { alias: String },
    AliasAlreadyExists { alias: String },
    Editor { source: String },
    CommandExec { source: String },
    ExecutableTempfile { source: String },
}

impl fmt::Display for PierError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PierError::NoConfigFile => {
                write!(f, "No default config file found. See help for more info.")
            }
            PierError::ConfigRead { path, source } => {
                write!(f, "Unable to read config from file {}: {} ", path, source)
            }
            PierError::ConfigParse { path, source } => {
                write!(f, "Unable to parse toml config from file {}: {}", path, source)
            }
            PierError::ConfigWrite { path, source } => {
                write!(f, "Unable to write config to {}: {}", path, source)
            }
            PierError::ConfigInitExists { path } => {
                write!(f, "Cannot initialize config at {}, file already exists.", path)
            }
            PierError::CreateDirectory { source } => {
                write!(f, "Failed to create directory. {}", source)
            }
            PierError::NoScriptsExists => {
                write!(f, "No scripts exist. Would you like to add a new script?")
            }
            PierError::AliasNotFound { alias } => {
                write!(f, "AliasNotFound: No script found by alias {}", alias)
            }
            PierError::AliasAlreadyExists { alias } => {
                write!(f, "AliasAlreadyExists:  {}", alias)
            }
            PierError::Editor { source } => {
                write!(f, "EditorError: Failed when trying to get input from editor {}", source)
            }
            PierError::CommandExec { source } => {
                write!(f, "Command execution failed with: {}", source)
            }
            PierError::ExecutableTempfile { source } => {
                write!(f, "Failed when trying to create executable tempfile. {}", source)
            }
        }
    }
}
