//! Minimal terminfo database reader and parameterized string expansion,
//! enough to colour output on a terminal.

use std::collections::HashMap;
use std::fs;
use std::path::PathBuf;

const STRING_NAMES: &[(usize, &str)] = &[
    (39, "sgr0"),
    (131, "sgr"),
    (297, "op"),
    (359, "setaf"),
    (360, "setab"),
];

const NUMBER_NAMES: &[(usize, &str)] = &[(13, "colors")];

pub struct TermInfo {
    pub strings: HashMap<String, Vec<u8>>,
    pub numbers: HashMap<String, i32>,
}

fn db_path_for_term(term: &str) -> Option<PathBuf> {
    let first_char = term.chars().next()?;
    let mut dirs: Vec<PathBuf> = Vec::new();
    if let Some(dir) = std::env::var_os("TERMINFO") {
        dirs.push(PathBuf::from(dir));
    }
    if let Ok(list) = std::env::var("TERMINFO_DIRS") {
        for d in list.split(':') {
            if d.is_empty() {
                dirs.push(PathBuf::from("/usr/share/terminfo"));
            } else {
                dirs.push(PathBuf::from(d));
            }
        }
    } else {
        if let Some(mut home) = crate::config::home_dir() {
            home.push(".terminfo");
            dirs.push(home);
        }
        dirs.push(PathBuf::from("/etc/terminfo"));
        dirs.push(PathBuf::from("/lib/terminfo"));
        dirs.push(PathBuf::from("/usr/share/terminfo"));
        dirs.push(PathBuf::from("/boot/system/data/terminfo"));
    }
    for mut p in dirs {
        if fs::metadata(&p).is_ok() {
            p.push(first_char.to_string());
            p.push(term);
            if fs::metadata(&p).is_ok() {
                return Some(p);
            }
            p.pop();
            p.pop();
            p.push(format!("{:x}", first_char as usize));
            p.push(term);
            if fs::metadata(&p).is_ok() {
                return Some(p);
            }
        }
    }
    None
}

fn read_u16(data: &[u8], at: usize) -> Option<i32> {
    let b = data.get(at..at + 2)?;
    let v = u16::from_le_bytes([b[0], b[1]]);
    Some(if v == 0xffff { -1 } else { v as i32 })
}

fn read_u32(data: &[u8], at: usize) -> Option<i32> {
    let b = data.get(at..at + 4)?;
    let v = u32::from_le_bytes([b[0], b[1], b[2], b[3]]);
    Some(if v == 0xffff_ffff { -1 } else { v as i32 })
}

impl TermInfo {
    pub fn from_env() -> Option<TermInfo> {
        let term = std::env::var("TERM").ok()?;
        let path = db_path_for_term(&term)?;
        let data = fs::read(path).ok()?;
        TermInfo::parse(&data)
    }

    fn parse(data: &[u8]) -> Option<TermInfo> {
        let magic = read_u16(data, 0)?;
        let number_size = match magic {
            0o432 => 2,
            0o1036 => 4,
            _ => return None,
        };
        let names_bytes = read_u16(data, 2)? as usize;
        let bools_count = read_u16(data, 4)? as usize;
        let numbers_count = read_u16(data, 6)? as usize;
        let strings_count = read_u16(data, 8)? as usize;
        let string_table_bytes = read_u16(data, 10)? as usize;

        let mut pos = 12 + names_bytes + bools_count;
        if pos % 2 == 1 {
            pos += 1;
        }
        let mut numbers = HashMap::new();
        for i in 0..numbers_count {
            let v = if number_size == 2 {
                read_u16(data, pos + i * 2)?
            } else {
                read_u32(data, pos + i * 4)?
            };
            if v >= 0 {
                if let Some((_, name)) = NUMBER_NAMES.iter().find(|(idx, _)| *idx == i) {
                    numbers.insert(name.to_string(), v);
                }
            }
        }
        pos += numbers_count * number_size;

        let offsets_start = pos;
        let table_start = offsets_start + strings_count * 2;
        let table = data.get(table_start..table_start + string_table_bytes)?;
        let mut strings = HashMap::new();
        for i in 0..strings_count {
            let off = read_u16(data, offsets_start + i * 2)?;
            if off < 0 {
                continue;
            }
            if let Some((_, name)) = STRING_NAMES.iter().find(|(idx, _)| *idx == i) {
                let off = off as usize;
                if off < table.len() {
                    let end = table[off..].iter().position(|&b| b == 0).map(|e| off + e).unwrap_or(table.len());
                    strings.insert(name.to_string(), table[off..end].to_vec());
                }
            }
        }
        Some(TermInfo { strings, numbers })
    }
}

#[derive(Clone, Debug)]
pub enum Param {
    Number(i32),
    Words(String),
}

#[derive(Default)]
struct Vars {
    sta: Vec<Param>,
    dyn_: Vec<Param>,
}

/// Expand a parameterized terminfo string.
pub fn expand(cap: &[u8], params: &[Param]) -> Option<Vec<u8>> {
    let mut out: Vec<u8> = Vec::new();
    let mut stack: Vec<Param> = Vec::new();
    let mut params: Vec<Param> = params.to_vec();
    while params.len() < 9 {
        params.push(Param::Number(0));
    }
    let mut vars = Vars { sta: vec![Param::Number(0); 26], dyn_: vec![Param::Number(0); 26] };

    let mut i = 0;
    // Conditional state: how deep we are skipping.
    while i < cap.len() {
        let c = cap[i];
        i += 1;
        if c != b'%' {
            out.push(c);
            continue;
        }
        let Some(&cmd) = cap.get(i) else { return None };
        i += 1;
        match cmd {
            b'%' => out.push(b'%'),
            b'c' => match stack.pop()? {
                Param::Number(n) => out.push(n as u8),
                Param::Words(s) => out.extend_from_slice(s.as_bytes()),
            },
            b's' => match stack.pop()? {
                Param::Words(s) => out.extend_from_slice(s.as_bytes()),
                Param::Number(n) => out.extend_from_slice(n.to_string().as_bytes()),
            },
            b'd' => match stack.pop()? {
                Param::Number(n) => out.extend_from_slice(n.to_string().as_bytes()),
                Param::Words(_) => return None,
            },
            b'o' | b'x' | b'X' => match stack.pop()? {
                Param::Number(n) => {
                    let s = match cmd {
                        b'o' => format!("{:o}", n),
                        b'x' => format!("{:x}", n),
                        _ => format!("{:X}", n),
                    };
                    out.extend_from_slice(s.as_bytes());
                }
                Param::Words(_) => return None,
            },
            b'p' => {
                let idx = *cap.get(i)?;
                i += 1;
                if !(b'1'..=b'9').contains(&idx) {
                    return None;
                }
                stack.push(params[(idx - b'1') as usize].clone());
            }
            b'P' => {
                let name = *cap.get(i)?;
                i += 1;
                let v = stack.pop()?;
                if name.is_ascii_uppercase() {
                    vars.sta[(name - b'A') as usize] = v;
                } else if name.is_ascii_lowercase() {
                    vars.dyn_[(name - b'a') as usize] = v;
                } else {
                    return None;
                }
            }
            b'g' => {
                let name = *cap.get(i)?;
                i += 1;
                if name.is_ascii_uppercase() {
                    stack.push(vars.sta[(name - b'A') as usize].clone());
                } else if name.is_ascii_lowercase() {
                    stack.push(vars.dyn_[(name - b'a') as usize].clone());
                } else {
                    return None;
                }
            }
            b'\'' => {
                let ch = *cap.get(i)?;
                i += 1;
                if *cap.get(i)? != b'\'' {
                    return None;
                }
                i += 1;
                stack.push(Param::Number(ch as i32));
            }
            b'{' => {
                let mut n: i32 = 0;
                loop {
                    let d = *cap.get(i)?;
                    i += 1;
                    if d == b'}' {
                        break;
                    }
                    if !d.is_ascii_digit() {
                        return None;
                    }
                    n = n * 10 + (d - b'0') as i32;
                }
                stack.push(Param::Number(n));
            }
            b'l' => match stack.pop()? {
                Param::Words(s) => stack.push(Param::Number(s.len() as i32)),
                Param::Number(_) => return None,
            },
            b'+' | b'-' | b'*' | b'/' | b'm' | b'&' | b'|' | b'^' | b'=' | b'>' | b'<' | b'A' | b'O' => {
                let b = match stack.pop()? {
                    Param::Number(n) => n,
                    _ => return None,
                };
                let a = match stack.pop()? {
                    Param::Number(n) => n,
                    _ => return None,
                };
                let r = match cmd {
                    b'+' => a.wrapping_add(b),
                    b'-' => a.wrapping_sub(b),
                    b'*' => a.wrapping_mul(b),
                    b'/' => {
                        if b == 0 {
                            return None;
                        }
                        a / b
                    }
                    b'm' => {
                        if b == 0 {
                            return None;
                        }
                        a % b
                    }
                    b'&' => a & b,
                    b'|' => a | b,
                    b'^' => a ^ b,
                    b'=' => (a == b) as i32,
                    b'>' => (a > b) as i32,
                    b'<' => (a < b) as i32,
                    b'A' => (a != 0 && b != 0) as i32,
                    b'O' => (a != 0 || b != 0) as i32,
                    _ => unreachable!(),
                };
                stack.push(Param::Number(r));
            }
            b'!' | b'~' => {
                let a = match stack.pop()? {
                    Param::Number(n) => n,
                    _ => return None,
                };
                stack.push(Param::Number(if cmd == b'!' { (a == 0) as i32 } else { !a }));
            }
            b'i' => {
                if let Param::Number(n) = params[0] {
                    params[0] = Param::Number(n + 1);
                }
                if let Param::Number(n) = params[1] {
                    params[1] = Param::Number(n + 1);
                }
            }
            b'?' => {}
            b't' => {
                let cond = match stack.pop()? {
                    Param::Number(n) => n != 0,
                    Param::Words(s) => !s.is_empty(),
                };
                if !cond {
                    // Skip to the matching %e or %; at this nesting level.
                    let mut level = 0;
                    loop {
                        let pos = find_percent(cap, i)?;
                        let c2 = *cap.get(pos + 1)?;
                        i = pos + 2;
                        match c2 {
                            b'?' => level += 1,
                            b';' => {
                                if level == 0 {
                                    break;
                                }
                                level -= 1;
                            }
                            b'e' => {
                                if level == 0 {
                                    break;
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
            b'e' => {
                // We reached an else branch after executing the then
                // branch: skip to the matching %;.
                let mut level = 0;
                loop {
                    let pos = find_percent(cap, i)?;
                    let c2 = *cap.get(pos + 1)?;
                    i = pos + 2;
                    match c2 {
                        b'?' => level += 1,
                        b';' => {
                            if level == 0 {
                                break;
                            }
                            level -= 1;
                        }
                        _ => {}
                    }
                }
            }
            b';' => {}
            b':' | b'0'..=b'9' | b'.' | b'#' | b' ' => {
                // printf style formatting: parse flags/width/precision then
                // the conversion character.
                let mut j = i - 1;
                while j < cap.len() && matches!(cap[j], b':' | b'-' | b'+' | b'#' | b' ' | b'0'..=b'9' | b'.') {
                    j += 1;
                }
                let conv = *cap.get(j)?;
                let spec = String::from_utf8_lossy(&cap[i - 1..j]).trim_start_matches(':').to_string();
                i = j + 1;
                let (flags, rest) = split_flags(&spec);
                let (width, precision) = split_width(rest);
                let v = stack.pop()?;
                let text = match (conv, v) {
                    (b'd', Param::Number(n)) => n.to_string(),
                    (b'o', Param::Number(n)) => format!("{:o}", n),
                    (b'x', Param::Number(n)) => format!("{:x}", n),
                    (b'X', Param::Number(n)) => format!("{:X}", n),
                    (b's', Param::Words(s)) => {
                        let mut s = s;
                        if let Some(p) = precision {
                            s.truncate(p);
                        }
                        s
                    }
                    _ => return None,
                };
                let mut text = text;
                if let Some(w) = width {
                    while text.len() < w {
                        if flags.contains('-') {
                            text.push(' ');
                        } else {
                            text.insert(0, ' ');
                        }
                    }
                }
                out.extend_from_slice(text.as_bytes());
            }
            _ => return None,
        }
    }
    Some(out)
}

fn find_percent(cap: &[u8], from: usize) -> Option<usize> {
    let mut i = from;
    while i + 1 < cap.len() {
        if cap[i] == b'%' {
            return Some(i);
        }
        i += 1;
    }
    None
}

fn split_flags(spec: &str) -> (String, &str) {
    let mut flags = String::new();
    let mut idx = 0;
    for (i, c) in spec.char_indices() {
        if matches!(c, '-' | '+' | '#' | ' ') {
            flags.push(c);
            idx = i + 1;
        } else {
            break;
        }
    }
    (flags, &spec[idx..])
}

fn split_width(rest: &str) -> (Option<usize>, Option<usize>) {
    let mut parts = rest.splitn(2, '.');
    let width = parts.next().and_then(|w| w.parse().ok());
    let precision = parts.next().and_then(|p| p.parse().ok());
    (width, precision)
}

/// A colour capable terminal writer.
pub struct ColorTerm {
    info: TermInfo,
    num_colors: i32,
}

impl ColorTerm {
    /// Returns `None` when `TERM` is unset or has no database entry.
    pub fn new() -> Option<ColorTerm> {
        let info = TermInfo::from_env()?;
        let num_colors = if info.strings.contains_key("setaf") && info.strings.contains_key("setab") {
            info.numbers.get("colors").copied().unwrap_or(0)
        } else {
            0
        };
        Some(ColorTerm { info, num_colors })
    }

    /// Escape sequence selecting a foreground colour (if supported).
    pub fn fg(&self, color: i32) -> Option<Vec<u8>> {
        if self.num_colors > color {
            let cap = self.info.strings.get("setaf")?;
            expand(cap, &[Param::Number(color)])
        } else {
            None
        }
    }

    /// Escape sequence resetting all attributes.
    pub fn reset(&self) -> Option<Vec<u8>> {
        if let Some(cap) = self.info.strings.get("sgr0") {
            return expand(cap, &[]);
        }
        if let Some(cap) = self.info.strings.get("sgr") {
            return expand(cap, &[Param::Number(0); 9]);
        }
        if let Some(cap) = self.info.strings.get("op") {
            return expand(cap, &[]);
        }
        None
    }
}
