    pub fn new(content: &str) -> Cell {
        Cell { lines: content.lines().map(|s| s.to_string()).collect(), color: None }
    }

    pub fn with_color(mut self, color: i32) -> Cell {
        self.color = Some(color);
        self
    }

    fn width(&self) -> usize {
        self.lines.iter().map(|l| display_width(l)).max().unwrap_or(0)
    }

    fn height(&self) -> usize {
        self.lines.len()
    }
}

/// Width of a string ignoring ANSI escape sequences.
fn display_width(text: &str) -> usize {
    #[derive(PartialEq, Clone, Copy)]
    enum State {
        Normal,
        Escape,
        Csi,
    }
    let width = UnicodeWidthStr::width(text);
    let mut state = State::Normal;
    let mut hidden = 0;
    for c in text.chars() {
        state = match (state, c) {
            (State::Normal, '\u{1b}') => State::Escape,
            (State::Escape, '[') => State::Csi,
            (State::Escape, _) => State::Normal,
            (State::Csi, '\u{40}'..='\u{7e}') => State::Normal,
            _ => state,
        };
        if state != State::Normal {
            hidden += 1;
        }
    }
    width.saturating_sub(hidden)
}

pub struct Table {
    titles: Vec<Cell>,
    rows: Vec<Vec<Cell>>,
}

struct Writer<'a> {
    out: &'a mut dyn Write,
    term: Option<ColorTerm>,
}

impl Table {
    pub fn new(titles: Vec<Cell>) -> Table {
        Table { titles, rows: Vec::new() }
    }

    pub fn add_row(&mut self, row: Vec<Cell>) {
        self.rows.push(row);
    }

    fn column_count(&self) -> usize {
        self.rows.iter().map(|r| r.len()).chain(std::iter::once(self.titles.len())).max().unwrap_or(0)
    }

    fn column_widths(&self) -> Vec<usize> {
        let n = self.column_count();
        (0..n)
            .map(|i| {
                let t = self.titles.get(i).map(|c| c.width()).unwrap_or(0);
                self.rows.iter().map(|r| r.get(i).map(|c| c.width()).unwrap_or(0)).fold(t, usize::max)
            })
            .collect()
    }

    /// Print to stdout, using colours when stdout is a terminal.
    pub fn printstd(&self) {
        let stdout = io::stdout();
        let mut lock = stdout.lock();
        let term = if lock.is_terminal() { ColorTerm::new() } else { None };
        let mut w = Writer { out: &mut lock, term };
        let _ = self.print(&mut w);
    }

    fn print(&self, w: &mut Writer<'_>) -> io::Result<()> {
        let widths = self.column_widths();
        self.print_line(w, &widths)?;
        self.print_row(w, &self.titles, &widths)?;
        self.print_line(w, &widths)?;
        for row in &self.rows {
            self.print_row(w, row, &widths)?;
        }
        self.print_line(w, &widths)?;
        w.out.flush()
    }

    fn print_line(&self, w: &mut Writer<'_>, widths: &[usize]) -> io::Result<()> {
        let mut s = String::new();
        s.push_str(LINE);
        for (i, width) in widths.iter().enumerate() {
            for _ in 0..width + 2 {
                s.push_str(LINE);
            }
            if i + 1 < widths.len() {
                s.push_str(LINE);
            }
        }
        s.push_str(LINE);
        s.push('\n');
        w.out.write_all(s.as_bytes())
    }

    fn print_row(&self, w: &mut Writer<'_>, row: &[Cell], widths: &[usize]) -> io::Result<()> {
        let empty = Cell::new("");
        let height = row.iter().map(|c| c.height()).max().unwrap_or(0).max(1);
        for line_idx in 0..height {
            w.out.write_all(SEP.as_bytes())?;
            for (j, width) in widths.iter().enumerate() {
                w.out.write_all(b" ")?;
                let cell = row.get(j).unwrap_or(&empty);
                let content = cell.lines.get(line_idx).map(|s| s.as_str()).unwrap_or("");
                let fill = width.saturating_sub(display_width(content));
                let mut colored = false;
                if let (Some(term), Some(color)) = (&w.term, cell.color) {
                    if let Some(seq) = term.fg(color) {
                        w.out.write_all(&seq)?;
                        colored = true;
                    }
                }
                w.out.write_all(content.as_bytes())?;
                for _ in 0..fill {
                    w.out.write_all(b" ")?;
                }
                if let Some(term) = &w.term {
                    if colored || cell.color.is_some() {
                        if let Some(seq) = term.reset() {
                            w.out.write_all(&seq)?;
                        }
                    }
                }
                w.out.write_all(b" ")?;
                w.out.write_all(SEP.as_bytes())?;
            }
            w.out.write_all(b"\n")?;
        }
        Ok(())
    }
}
