        for (i, width) in widths.iter().enumerate() {
            for _ in 0..width + 2 {
                s.push_str(LINE);
            }
            if i + 1 < widths.len() {
                s.push_str(LINE);
            }
        }
        s.push_str(LINE);
        s.push('\n');
        w.out.write_all(s.as_bytes())
    }

    fn print_row(&self, w: &mut Writer<'_>, row: &[Cell], widths: &[usize]) -> io::Result<()> {
        let empty = Cell::new("");
        let height = row.iter().map(|c| c.height()).max().unwrap_or(0).max(1);
        for line_idx in 0..height {
            w.out.write_all(SEP.as_bytes())?;
            for (j, width) in widths.iter().enumerate() {
                w.out.write_all(b" ")?;
                let cell = row.get(j).unwrap_or(&empty);
                let content = cell.lines.get(line_idx).map(|s| s.as_str()).unwrap_or("");
                let fill = width.saturating_sub(display_width(content));
                let mut colored = false;
                if let (Some(term), Some(color)) = (&w.term, cell.color) {
                    if let Some(seq) = term.fg(color) {
                        w.out.write_all(&seq)?;
                        colored = true;
                    }
                }
                w.out.write_all(content.as_bytes())?;
                for _ in 0..fill {
                    w.out.write_all(b" ")?;
                }
                if let Some(term) = &w.term {
                    if colored || cell.color.is_some() {
                        if let Some(seq) = term.reset() {
                            w.out.write_all(&seq)?;
                        }
                    }
                }
                w.out.write_all(b" ")?;
                w.out.write_all(SEP.as_bytes())?;
            }
            w.out.write_all(b"\n")?;
        }
        Ok(())
    }
}
