/// Default interpreter used when the configuration does not specify one.
fn default_interpreter() -> Vec<String> {
    vec!["/bin/sh".to_string(), "-c".to_string()]
}

/// Six random alphanumeric characters.
fn random_suffix() -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut seed: u64 = {
        let t = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x9E3779B97F4A7C15);
        t ^ ((std::process::id() as u64) << 32) ^ (&t as *const u64 as u64)
    };
    if let Ok(bytes) = fs::read("/dev/urandom").or_else(|_| Err(())).and_then(|_| Err::<Vec<u8>, ()>(())) {
        let _ = bytes;
    }
    if let Ok(mut f) = fs::File::open("/dev/urandom") {
        use std::io::Read;
        let mut buf = [0u8; 8];
        if f.read_exact(&mut buf).is_ok() {
            seed ^= u64::from_le_bytes(buf);
        }
    }
    let mut out = String::new();
    for _ in 0..6 {
        // xorshift64*
        seed ^= seed >> 12;
        seed ^= seed << 25;
        seed ^= seed >> 27;
        let r = seed.wrapping_mul(0x2545F4914F6CDD1D);
        out.push(CHARS[(r >> 33) as usize % CHARS.len()] as char);
    }
    out
}

/// Temporary directory holding an executable copy of a script.
struct ScriptDir {
    path: PathBuf,
}

impl ScriptDir {
    fn create() -> Result<ScriptDir, PierError> {
        let base = std::env::temp_dir();
        let mut attempts = 0;
        loop {
            let path = base.join(format!("pier{}", random_suffix()));
            match fs::create_dir(&path) {
                Ok(()) => return Ok(ScriptDir { path }),
                Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists && attempts < 1 << 31 => {
                    attempts += 1;
                    continue;
                }
                Err(e) => {
                    return Err(PierError::ExecutableTempfile {
                        source: format!("{} at path {:?}", e, path),
                    })
                }
            }
        }
    }
}

impl Drop for ScriptDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.path);
    }
}

fn exec_error(e: std::io::Error) -> PierError {
    PierError::CommandExec { source: e.to_string() }
}

/// Run `script` with the given interpreter and arguments and return the
/// exit status of the child process.
pub fn run(
    alias: &str,
    script: &Script,
    interpreter: Option<&[String]>,
    args: &[String],
    verbose: bool,
) -> Result<ExitStatus, PierError> {
    let interpreter: Vec<String> = match interpreter {
        Some(i) => i.to_vec(),
        None => default_interpreter(),
    };

    if verbose {
        println!("Starting script {:?}", alias);
        println!("-------------------------");
    }

    let status = if script.command.starts_with("#!") {
        // Scripts with a shebang are executed directly from a temporary file.
        let dir = ScriptDir::create()?;
        let file_path = dir.path.join(alias);
        let write_result = (|| -> std::io::Result<()> {
            let mut f = fs::OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .open(&file_path)?;
            f.write_all(script.command.as_bytes())?;
            f.flush()?;
            drop(f);
            let mut perms = fs::metadata(&file_path)?.permissions();
            use std::os::unix::fs::PermissionsExt;
            perms.set_mode(0o500);
            fs::set_permissions(&file_path, perms)?;
            Ok(())
        })();
        if let Err(e) = write_result {
            return Err(PierError::ExecutableTempfile { source: e.to_string() });
        }
        let status = Command::new(&file_path)
            .args(args)
            .stdin(Stdio::inherit())
            .stdout(Stdio::inherit())
            .stderr(Stdio::inherit())
            .status()
            .map_err(exec_error)?;
        drop(dir);
        status
    } else {
        if interpreter.is_empty() {
            crate::panic_exit("src/script.rs:52:44", "index out of bounds: the len is 0 but the index is 0");
        }
        Command::new(&interpreter[0])
            .args(&interpreter[1..])
            .arg(&script.command)
            .arg(alias)
            .args(args)
            .stdin(Stdio::inherit())
            .stdout(Stdio::inherit())
            .stderr(Stdio::inherit())
            .status()
            .map_err(exec_error)?
    };

    if verbose {
        println!("-------------------------");
        println!("Script complete");
    }

    Ok(status)
}

