    let status = Command::new(&editor)
        .arg(&path)
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .status();
    match status {
        Ok(s) if s.success() => {}
        _ => return Err(failure()),
    }

    fs::read_to_string(&path).map_err(|_| failure())
}
