/// Terminate the process the way an unrecoverable runtime error would.
pub fn panic_exit(location: &str, message: &str) -> ! {
    let _ = std::io::stdout().flush();
    eprintln!("thread 'main' panicked at {}:\n{}", location, message);
    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
