/// Resolve the configuration path from the command line / environment /
/// default locations.
fn resolve_config_path(cli_path: &Option<String>) -> Result<PathBuf, PierError> {
    if let Some(p) = cli_path {
        return Ok(PathBuf::from(p));
    }
    config::find_default_config().ok_or(PierError::NoConfigFile)
}

struct Store {
    path: PathBuf,
    config: Config,
}

impl Store {
    fn load(cli_path: &Option<String>) -> Result<Store, PierError> {
        let path = resolve_config_path(cli_path)?;
        let config = Config::load(&path)?;
        Ok(Store { path, config })
    }

    fn save(&self) -> Result<(), PierError> {
        self.config.write(&self.path)
    }

    /// Scripts, failing when none exist.
    fn scripts(&self) -> Result<&BTreeMap<String, Script>, PierError> {
        match &self.config.scripts {
            Some(s) if !s.is_empty() => Ok(s),
            _ => Err(PierError::NoScriptsExists),
        }
    }

    fn scripts_mut(&mut self) -> &mut BTreeMap<String, Script> {
        self.config.scripts.get_or_insert_with(BTreeMap::new)
    }

    fn fetch(&self, alias: &str) -> Result<&Script, PierError> {
        self.scripts()?
            .get(alias)
            .ok_or_else(|| PierError::AliasNotFound { alias: alias.to_string() })
    }

    /// Fetch without the "no scripts" check.
    fn fetch_any(&self, alias: &str) -> Result<Script, PierError> {
        self.config
            .scripts
            .as_ref()
            .and_then(|s| s.get(alias))
            .cloned()
            .ok_or_else(|| PierError::AliasNotFound { alias: alias.to_string() })
    }

    fn exists(&self, alias: &str) -> bool {
        self.config.scripts.as_ref().map_or(false, |s| s.contains_key(alias))
    }

    fn add(&mut self, alias: &str, script: Script, force: bool) -> Result<(), PierError> {
        if !force && self.exists(alias) {
            return Err(PierError::AliasAlreadyExists { alias: alias.to_string() });
        }
        self.scripts_mut().insert(alias.to_string(), script);
        Ok(())
    }

    fn remove(&mut self, alias: &str) -> Result<Script, PierError> {
        self.scripts()?;
        self.scripts_mut()
            .remove(alias)
            .ok_or_else(|| PierError::AliasNotFound { alias: alias.to_string() })
    }
}

fn run(cli: cli::Cli) -> Result<i32, PierError> {
    match cli.command {
        Command::ConfigInit => config_init(&cli.config_file),
        Command::Add { alias, description, tags, force, command } => {
            let mut store = Store::load(&cli.config_file)?;
            let command = match command {
                Some(c) => c,
                None => script::open_editor("")?,
            };
            let script = Script { command, description, reference: None, tags };
            store.add(&alias, script, force)?;
            println!("Added {}", alias);
            store.save()?;
            Ok(0)
        }
        Command::Copy { from, to } => {
            let mut store = Store::load(&cli.config_file)?;
            if store.exists(&to) {
                return Err(PierError::AliasAlreadyExists { alias: to });
            }
            let script = store.fetch_any(&from)?;
            store.scripts_mut().insert(to.clone(), script);
            println!("Copy from alias {} to new alias {}", from, to);
            store.save()?;
            Ok(0)
        }
        Command::Move { from, to, force } => {
            let mut store = Store::load(&cli.config_file)?;
            if !force && store.exists(&to) {
                return Err(PierError::AliasAlreadyExists { alias: to });
            }
            let script = store.fetch_any(&from)?;
            store.scripts_mut().remove(&from);
            store.scripts_mut().insert(to.clone(), script);
            println!("Move from alias {} to new alias {}", from, to);
            store.save()?;
            Ok(0)
        }
        Command::Edit { alias } => {
            let mut store = Store::load(&cli.config_file)?;
            let current = store.fetch(&alias)?.clone();
            let command = script::open_editor(&current.command)?;
            let mut updated = current;
            updated.command = command;
            store.scripts_mut().insert(alias.clone(), updated);
            println!("Edited {}", alias);
            store.save()?;
            Ok(0)
        }
        Command::Remove { alias } => {
            let mut store = Store::load(&cli.config_file)?;
            store.remove(&alias)?;
            println!("Removed {}", alias);
            store.save()?;
            Ok(0)
        }
        Command::Show { alias } => {
            let store = Store::load(&cli.config_file)?;
            let script = store.fetch(&alias)?;
            println!("{}", script.command);
            Ok(0)
        }
        Command::List { list_aliases, cmd_full, cmd_width, tags } => {
            let store = Store::load(&cli.config_file)?;
            list(&store, list_aliases, cmd_full, cmd_width, tags)?;
            Ok(0)
        }
        Command::Run { alias, args } => {
            let store = Store::load(&cli.config_file)?;
            let script = store.fetch(&alias)?;
            let status = script::run(
                &alias,
                script,
                store.config.default.interpreter.as_deref(),
                &args,
                cli.verbose,
            )?;
            Ok(status.code().unwrap_or(1))
        }
    }
}

fn config_init(cli_path: &Option<String>) -> Result<i32, PierError> {
    let path = match cli_path {
        Some(p) => PathBuf::from(p),
        None => match config::find_default_config() {
            Some(existing) => {
                return Err(PierError::ConfigInitExists { path: existing.to_string_lossy().into_owned() })
            }
            None => config::default_init_path().unwrap_or_else(|| PathBuf::from("pier.toml")),
        },
    };
    if path.exists() {
        return Err(PierError::ConfigInitExists { path: path.to_string_lossy().into_owned() });
    }
    if let Some(parent) = path.parent() {
        if !parent.exists() {
            std::fs::create_dir(parent)
                .map_err(|e| PierError::CreateDirectory { source: e.to_string() })?;
        }
    }
    let config = Config::example();
    println!("Added hello-pier");
    config.write(&path)?;
    Ok(0)
}

fn list(
    store: &Store,
