    /// structure is checked.
    fn datetime(&mut self, span: Span, date: &'a str, colon_eaten: bool) -> PResult<Value> {
        let _ = date;
        let start = span.start;
        let invalid = |at: usize| (at, "invalid date".to_string());

        // Space separated date and time.
        let mut lookahead = self.tokens.clone();
        if let Ok(Some((_, Token::Whitespace(" ")))) = lookahead.next() {
            if let Ok(Some((_, Token::Keylike(_)))) = lookahead.next() {
                self.tokens.next().lex()?;
                self.tokens.next().lex()?;
            }
        }

        if colon_eaten || self.tokens.eat(Token::Colon).lex()? {
            // minutes
            match self.tokens.next().lex()? {
                Some((_, Token::Keylike(_))) => {}
                _ => return Err(invalid(start)),
            }
            // seconds
            self.tokens.expect(Token::Colon).lex()?;
            match self.tokens.next().lex()? {
                Some((_, Token::Keylike(_))) => {}
                _ => return Err(invalid(start)),
            }
            // fractional seconds
            if self.tokens.eat(Token::Period).lex()? {
                match self.tokens.next().lex()? {
                    Some((_, Token::Keylike(_))) => {}
                    _ => return Err(invalid(start)),
                }
            }
            // offset
            if self.tokens.eat(Token::Plus).lex()? {
                match self.tokens.next().lex()? {
                    Some((_, Token::Keylike(_))) => {}
                    _ => return Err(invalid(start)),
                }
            }
            if self.tokens.eat(Token::Colon).lex()? {
                match self.tokens.next().lex()? {
                    Some((_, Token::Keylike(_))) => {}
                    _ => return Err(invalid(start)),
                }
            }
        }

        let end = self.tokens.current();
        Ok(Value::Datetime(self.input[start..end.min(self.input.len())].to_string()))
    }

