//! Greedy word wrapping used for help texts.
//!
//! Words are broken at whitespace; additionally a word may be split after a
//! hyphen that sits between two alphanumeric characters.  Words that do not
//! fit on a line of their own are left intact (overflowing the width).

use unicode_width::UnicodeWidthChar;

fn width_of(s: &str) -> usize {
    s.chars().map(|c| UnicodeWidthChar::width(c).unwrap_or(0)).sum()
}

/// Possible split points of a word: `(head, tail)` pairs, smallest head
/// first, ending with the unsplit word.
fn hyphen_splits(word: &str) -> Vec<(&str, &str)> {
    let mut out = Vec::new();
    let mut chars = word.char_indices();
    let mut prev = match chars.next() {
        None => return vec![(word, "")],
        Some((_, c)) => c,
    };
    let (mut idx, mut cur) = match chars.next() {
        None => return vec![(word, "")],
        Some((i, c)) => (i, c),
    };
    for (i, next) in chars {
        if prev.is_alphanumeric() && cur == '-' && next.is_alphanumeric() {
            let (head, tail) = word.split_at(idx + 1);
            out.push((head, tail));
        }
        prev = cur;
        idx = i;
        cur = next;
    }
    out.push((word, ""));
    out
}

/// Wrap a single line of text to `width` columns.
pub fn wrap_line(source: &str, width: usize) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    let mut start = 0usize;
    let mut split = 0usize;
    let mut split_len = 0usize;
    let mut line_width = 0usize;
    let mut line_width_at_split = 0usize;
    let mut in_whitespace = false;

    for (idx, ch) in source.char_indices() {
        if start >= source.len() {
            break;
        }
        let char_width = UnicodeWidthChar::width(ch).unwrap_or(0);
        let char_len = ch.len_utf8();
        if ch.is_whitespace() {
            if in_whitespace {
                split_len += char_len;
            } else {
                split = idx;
                split_len = char_len;
            }
            line_width_at_split = line_width + char_width;
            in_whitespace = true;
        } else if line_width + char_width > width {
            in_whitespace = false;
            let remaining = &source[split + split_len..];
            let final_word = match remaining.find(char::is_whitespace) {
                Some(i) => &remaining[..i],
                None => remaining,
            };
            let splits = hyphen_splits(final_word);
            for (head, _) in splits.iter().rev() {
                if line_width_at_split + width_of(head) <= width {
                    split += split_len + head.len();
                    split_len = 0;
                    line_width_at_split += width_of(head);
                    break;
                }
            }
            if start >= split {
                // The word does not fit at all: emit its smallest part.
                split = start + splits[0].0.len();
                split_len = 0;
                line_width_at_split = line_width;
            }
            if start < split {
                lines.push(source[start..split].to_string());
                start = split + split_len;
                line_width = line_width - line_width_at_split + char_width;
                continue;
            }
        } else {
            in_whitespace = false;
        }
        line_width += char_width;
    }

    if start < source.len() {
        lines.push(source[start..].to_string());
    }
    lines
}

/// Wrap every line of `text` separately and join the result.
pub fn fill(text: &str, width: usize) -> String {
    text.lines()
        .map(|line| wrap_line(line, width).join("\n"))
        .collect::<Vec<_>>()
        .join("\n")
}
