/// Total terminal width assumed for help output.
const TERM_WIDTH: usize = 120;
/// Width of `--config-file <path>` (the longest option display).
const LONGEST_OPT: usize = 20;

const CONFIG_SHORT_HELP: &str = "Sets a custom config file";
const CONFIG_LONG_HELP: &str = "Sets a custom config file.

DEFAULT PATH is otherwise determined in this order:

- $PIER_CONFIG_PATH (environment variable if set)

- pier.toml (in the current directory)

- $XDG_CONFIG_HOME/pier/config.toml

- $XDG_CONFIG_HOME/pier/config

- $XDG_CONFIG_HOME/pier.toml

- $HOME/.pier.toml

- $HOME/.pier
";

fn text_width(s: &str) -> usize {
    use unicode_width::UnicodeWidthChar;
    s.chars().map(|c| UnicodeWidthChar::width(c).unwrap_or(0)).sum()
}

/// The `-c, --config-file <path>` entry of the OPTIONS section, laid out
/// like the rest of the help: the description follows the switch (short
/// help) or starts on the next line (long help), continuation lines are
/// indented and the text is wrapped to the terminal width.
fn config_entry(long: bool) -> String {
    let env_value = std::env::var_os("PIER_CONFIG_PATH")
        .map(|v| v.to_string_lossy().into_owned())
        .unwrap_or_default();
    let spec = format!(" [env: PIER_CONFIG_PATH={}]", env_value);
    let base = if long { CONFIG_LONG_HELP } else { CONFIG_SHORT_HELP };
    let mut help = format!("{}{}", base, spec);

    let indent = if long { 12 } else { LONGEST_OPT + 12 };
    let too_long = indent + text_width(base) + text_width(&spec) >= TERM_WIDTH;
    if too_long && indent <= TERM_WIDTH {
        help = crate::wrap::fill(&help, TERM_WIDTH - indent);
    }

    let mut out = String::from("    -c, --config-file <path>    ");
    let pad = " ".repeat(indent);
    let mut lines = help.lines();
    if long {
        out.push('\\n');
        out.push_str(&pad);
    }
    if let Some(first) = lines.next() {
        out.push_str(first);
    }
    for line in lines {
        out.push('\\n');
        out.push_str(&pad);
        out.push_str(line);
    }
    if long && !help.contains('\\n') {
        out.push('\\n');
    }
    out
}''')

