/// Parse a document into header tables (syntax check only).
pub fn parse_tables(input: &str) -> Result<Vec<RawTable>, TomlError> {
    let mut parser = Parser::new(input);
    match parser.tables() {
        Ok(mut t) => {
            for table in &mut t {
                table.line = parser.to_line(table.at);
            }
            Ok(t)
        }
        Err((at, message)) => {
            Err(TomlError { message, key: Vec::new(), line: Some(parser.to_line(at)) })
        }
    }
}

/// Determines the order in which tables are processed.  Tables are grouped
/// by their key path: once a key is entered, all tables below that key are
/// handled (in document order) before moving on to the next key.  Conflicts
/// (a table defined twice, or redefined as an array) are reported at the
/// point where they would be noticed.
struct Walker<'a> {
    tables: &'a [RawTable],
    visited: Vec<bool>,
    order: Vec<usize>,
    error: Option<(usize, String)>,
}

impl<'a> Walker<'a> {
    fn new(tables: &'a [RawTable]) -> Self {
        Walker { tables, visited: vec![false; tables.len()], order: Vec::new(), error: None }
    }

    fn has_prefix(&self, idx: usize, prefix: &[String]) -> bool {
        let h = &self.tables[idx].header;
        h.len() >= prefix.len() && h[..prefix.len()] == prefix[..]
    }

    /// Visit all tables sharing the first `depth` header components with
    /// `cur_parent`, starting the scan at `cur`.
    fn visit(&mut self, depth: usize, mut cur_parent: usize, mut cur: usize) {
        let max = self.tables.len();
        loop {
            if self.error.is_some() || cur >= max {
                return;
            }
            let prefix: Vec<String> = self.tables[cur_parent].header[..depth].to_vec();
            let next = (cur..max).find(|&i| !self.visited[i] && self.has_prefix(i, &prefix));
            let Some(pos) = next else { return };
            cur = pos;
            if cur_parent != pos {
                if self.tables[cur_parent].header == self.tables[pos].header {
                    let name = self.tables[pos].header.join(".");
                    self.error = Some((pos, format!("redefinition of table `{}`", name)));
                    return;
                }
                if self.tables[pos].header.len() < self.tables[cur_parent].header.len() {
                    cur_parent = pos;
                }
            }
            let table = &self.tables[pos];
            if depth != table.header.len() {
                let array = table.array && depth == table.header.len() - 1;
                if array {
                    // All elements of the array share the header; deeper
                    // tables are attached to the elements.
                    let header = table.header.clone();
                    for i in pos..max {
                        if !self.visited[i] && self.tables[i].array && self.tables[i].header == header {
                            self.visited[i] = true;
                            self.order.push(i);
                        }
                    }
                    self.visit(depth + 1, pos, 0);
                } else {
                    self.visit(depth + 1, pos, 0);
                }
                cur = pos + 1;
                continue;
            }
            if table.array {
                self.error = Some((pos, "table redefined as array".to_string()));
                return;
            }
            self.visited[pos] = true;
            self.order.push(pos);
        }
    }
}

/// Order in which the tables are processed, or the conflict that stops
/// processing.
pub fn table_order(tables: &[RawTable]) -> Result<Vec<usize>, Duplicate> {
    if tables.is_empty() {
        return Ok(Vec::new());
    }
    let mut walker = Walker::new(tables);
    walker.visit(0, 0, 0);
    match walker.error {
        None => Ok(walker.order),
        Some((pos, message)) => {
            let table = &tables[pos];
            Err(Duplicate {
                error: TomlError { message, key: table.header.clone(), line: Some(table.line) },
                path: table.header.clone(),
                visited: walker.order,
            })
        }
    }
}

/// Build the value tree from the given tables (by index, in order).
pub fn build_tree(tables: &[RawTable], indices: &[usize]) -> Table {
    let mut root = Table { entries: Vec::new(), starts: Vec::new(), header: true, defined: true };

    for &table_idx in indices {
        let table = &tables[table_idx];
        if table.header.is_empty() {
            root.entries.extend(plain_entries(&table.values));
            continue;
        }

        let mut cur: &mut Table = &mut root;
        let last_idx = table.header.len() - 1;
